INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (297, 'tt0245712', 55, 'Amores Perros', 2000, '/A4lH22nlFF7MdalGfcvSrlC1ttt.jpg', '{18,53}', 'A fatalistic car crash in Mexico city sets off a chain of events in the lives of three people: a supermodel, a young man wanting to run off with his sister-in-law, and a homeless man.', '[{"name": "Emilio Echevarría", "character": "El Chivo"}, {"name": "Gael García Bernal", "character": "Octavio"}, {"name": "Vanessa Bauche", "character": "Susana"}, {"name": "Goya Toledo", "character": "Valeria"}, {"name": "Álvaro Guerrero", "character": "Daniel"}]', 'Alejandro G. Iñárritu', NULL, '2026-07-13 21:30:57.989722');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (298, 'tt1562872', 61202, 'Zindagi Na Milegi Dobara', 2011, '/hKO9O715wYxjkQSEv47giCYcyO8.jpg', '{18,35,10749}', 'Three friends who were inseparable in childhood decide to go on a three-week-long bachelor road trip to Spain, in order to re-establish their bond and explore thrilling adventures, before one of them gets married. What will they learn of themselves and each other during the adventure?', '[{"name": "Hrithik Roshan", "character": "Arjun Saluja"}, {"name": "Abhay Deol", "character": "Kabir Dewan"}, {"name": "Farhan Akhtar", "character": "Imran Qureshi"}, {"name": "Katrina Kaif", "character": "Laila"}, {"name": "Kalki Koechlin", "character": "Natasha Arora"}]', 'Zoya Akhtar', NULL, '2026-07-13 21:30:58.560617');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (299, 'tt3741834', 334543, 'Lion', 2016, '/iBGRbLvg6kVc7wbS8wDdVHq6otm.jpg', '{18}', 'A five-year-old Indian boy gets lost on the streets of Calcutta, thousands of kilometers from home. He survives many challenges before being adopted by a couple in Australia; 25 years later, he sets out to find his lost family.', '[{"name": "Dev Patel", "character": "Saroo Brierley"}, {"name": "Rooney Mara", "character": "Lucy"}, {"name": "David Wenham", "character": "John Brierley"}, {"name": "Nicole Kidman", "character": "Sue Brierley"}, {"name": "Abhishek Bharate", "character": "Guddu"}]', 'Garth Davis', NULL, '2026-07-13 21:30:59.127522');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (300, 'tt0063522', 805, 'Rosemary''s Baby', 1968, '/uYgvlHceRFjAFbsNeMInYcLZLUb.jpg', '{18,27,53}', 'A young couple, Rosemary and Guy, moves into an infamous New York apartment building, known by frightening legends and mysterious events, with the purpose of starting a family.', '[{"name": "Mia Farrow", "character": "Rosemary Woodhouse"}, {"name": "John Cassavetes", "character": "Guy Woodhouse"}, {"name": "Ruth Gordon", "character": "Minnie Castevet"}, {"name": "Sidney Blackmer", "character": "Roman Castevet"}, {"name": "Maurice Evans", "character": "Hutch"}]', 'Roman Polanski', NULL, '2026-07-13 21:30:59.752744');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (301, 'tt34365591', 1383072, 'Mahavatar Narsimha', 2024, '/uGTF87VyfjtwwqRlT2apQg5YnEp.jpg', '{16,28,14,18}', 'Tyrannical demon Hiranyakashyap challenges Vishnu, proclaiming himself a god. However, his son Prahlad remains devoted to Vishnu, who appears as Narsimha to defeat the demon.', '[{"name": "Harjeet Walia", "character": "Lord Narsimha (voice)"}, {"name": "Aditya Raj Sharma", "character": "Hiranyakashipu (voice)"}, {"name": "Haripriya Matta", "character": "Prahlad (voice)"}, {"name": "Sanket Jaiswal", "character": "Narrator (voice)"}, {"name": "Priyanka Bhandari", "character": "Kayadhu (voice)"}]', 'Ashwin Kumar', NULL, '2026-07-13 21:31:00.313702');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (302, 'tt0499549', 19995, 'Avatar', 2009, '/gKY6q7SjCkAU6FqvqWybDYgUKIF.jpg', '{878,28,12}', 'In the 22nd century, a paraplegic Marine is dispatched to the moon Pandora on a unique mission, but becomes torn between following orders and protecting an alien civilization.', '[{"name": "Sam Worthington", "character": "Jake Sully"}, {"name": "Zoe Saldaña", "character": "Neytiri"}, {"name": "Sigourney Weaver", "character": "Dr. Grace Augustine"}, {"name": "Stephen Lang", "character": "Colonel Miles Quaritch"}, {"name": "Michelle Rodriguez", "character": "Trudy Chacon"}]', 'James Cameron', NULL, '2026-07-13 21:31:00.913568');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (303, 'tt0083987', 783, 'Gandhi', 1982, '/rOXftt7SluxskrFrvU7qFJa5zeN.jpg', '{18,36}', 'In the early years of the 20th century, Mohandas K. Gandhi, a British-trained lawyer, forsakes all worldly possessions to take up the cause of Indian independence. Faced with armed resistance from the British government, Gandhi adopts a policy of ''passive resistance'', endeavouring to win freedom for his people without resorting to bloodshed.', '[{"name": "Ben Kingsley", "character": "Mahatma Gandhi"}, {"name": "Candice Bergen", "character": "Margaret Bourke-White"}, {"name": "Edward Fox", "character": "General Dyer"}, {"name": "John Gielgud", "character": "Lord Irwin"}, {"name": "Trevor Howard", "character": "Judge Broomfield"}]', 'Richard Attenborough', NULL, '2026-07-13 21:31:01.483553');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (304, 'tt1220719', 14756, 'Ip Man', 2008, '/zyQQ7wFuCvH6MzJcUKy6N6ouMYs.jpg', '{18,28,36}', 'A semi-biographical account of Yip Man, the first martial arts master to teach the Chinese martial art of Wing Chun. The film focuses on events surrounding Ip that took place in the city of Foshan between the 1930s to 1940s during the Second Sino-Japanese War. Directed by Wilson Yip, the film stars Donnie Yen in the lead role, and features fight choreography by Sammo Hung.', '[{"name": "Donnie Yen", "character": "Yip Man"}, {"name": "Simon Yam", "character": "Zhou Qing Quan"}, {"name": "Lynn Hung Doi-Lam", "character": "Zhang Yong Cheng"}, {"name": "Hiroyuki Ikeuchi", "character": "General Miura"}, {"name": "Gordon Lam Ka-Tung", "character": "Captain Li Zhao"}]', 'Wilson Yip', NULL, '2026-07-13 21:31:02.083583');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (305, 'tt0371746', 1726, 'Iron Man', 2008, '/78lPtwv72eTNqFW9COBYI0dWDJa.jpg', '{28,878,12}', 'After being held captive in an Afghan cave, billionaire engineer Tony Stark creates a unique weaponized suit of armor to fight evil.', '[{"name": "Robert Downey Jr.", "character": "Tony Stark"}, {"name": "Terrence Howard", "character": "Rhodey"}, {"name": "Jeff Bridges", "character": "Obadiah Stane"}, {"name": "Gwyneth Paltrow", "character": "Pepper Potts"}, {"name": "Leslie Bibb", "character": "Christine Everhart"}]', 'Jon Favreau', NULL, '2026-07-13 21:31:02.663517');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (306, 'tt0064115', 642, 'Butch Cassidy and the Sundance Kid', 1969, '/gFmmykF1Ym3OGzENo50nZQaD1dx.jpg', '{37}', 'As the west rapidly becomes civilized, a pair of outlaws in 1890s Wyoming find themselves pursued by a posse and decide to flee to South America in hopes of evading the law.', '[{"name": "Paul Newman", "character": "Butch Cassidy"}, {"name": "Robert Redford", "character": "Sundance Kid"}, {"name": "Katharine Ross", "character": "Etta Place"}, {"name": "Strother Martin", "character": "Percy Garris"}, {"name": "Henry Jones", "character": "Bike Salesman"}]', 'George Roy Hill', NULL, '2026-07-13 21:31:03.218046');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (307, 'tt0118849', 21334, 'Children of Heaven', 1997, '/jWqh1CJWAEcxckMRrf6ARhIEh0R.jpg', '{18,10751}', 'Zohre''s shoes are gone; her older brother Ali lost them. They are poor, there are no shoes for Zohre until they come up with an idea: they will share one pair of shoes. School awaits.', '[{"name": "Amir Farrokh Hashemian", "character": "Ali"}, {"name": "Bahare Seddiqi", "character": "Zahra"}, {"name": "Nafise Jafar-Mohammadi", "character": "Roya"}, {"name": "Reza Naji", "character": "Ali''s Father"}, {"name": "Fereshte Sarabandi", "character": "Ali''s Mother"}]', 'Majid Majidi', NULL, '2026-07-13 21:31:03.789988');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (308, 'tt0169102', 19666, 'Lagaan: Once Upon a Time in India', 2001, '/yNX9lFRAFeNLNRIXdqZK9gYrYKa.jpg', '{12,18,36}', 'The year is 1893 and India is under British occupation. In a small village, the tyrannical Captain Russell has imposed an unprecedented land tax on its citizens. Outraged, Bhuvan, a rebellious farmer, rallies the villagers to publicly oppose the tax. Russell offers a novel way to settle the dispute: he challenges Bhuvan and his men to a game of cricket, a sport completely foreign to India. If Bhuvan and his men can defeat Russell''s team, the tax will be repealed.', '[{"name": "Aamir Khan", "character": "Bhuvan"}, {"name": "Gracy Singh", "character": "Gauri"}, {"name": "Rachel Shelley", "character": "Elizabeth Russell"}, {"name": "Paul Blackthorne", "character": "Captain Andrew Russell"}, {"name": "Suhasini Mulay", "character": "Yashoda"}]', 'Ashutosh Gowariker', NULL, '2026-07-13 21:31:04.35138');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (309, 'tt0031679', 3083, 'Mr. Smith Goes to Washington', 1939, '/nDjg1fbNyq15excNDl3acd2IqAk.jpg', '{35,18}', 'After the death of a United States Senator, the idealistic Jefferson Smith is appointed as his replacement in Washington. The naive and earnest new senator soon finds himself battling political corruption.', '[{"name": "James Stewart", "character": "Jefferson Smith"}, {"name": "Jean Arthur", "character": "Clarissa Saunders"}, {"name": "Claude Rains", "character": "Joseph Paine"}, {"name": "Edward Arnold", "character": "Jim Taylor"}, {"name": "Guy Kibbee", "character": "Governor Hopper"}]', 'Frank Capra', NULL, '2026-07-13 21:31:04.930839');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (310, 'tt10366460', 776503, 'CODA', 2021, '/BzVjmm8l23rPsijLiNLUzuQtyd.jpg', '{18,10402,10749}', 'As a CODA (Child of Deaf Adults), Ruby is the only hearing person in her deaf family. When the family''s fishing business is threatened, Ruby finds herself torn between pursuing her love of music and her fear of abandoning her parents.', '[{"name": "Emilia Jones", "character": "Ruby Rossi"}, {"name": "Marlee Matlin", "character": "Jackie Rossi"}, {"name": "Troy Kotsur", "character": "Frank Rossi"}, {"name": "Eugenio Derbez", "character": "Bernardo Villalobos"}, {"name": "Ferdia Walsh-Peelo", "character": "Miles"}]', 'Sian Heder', NULL, '2026-07-13 21:31:05.507112');
