INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (389, 'tt0075686', 703, 'Annie Hall', 1977, '/dEtjPywhDbAXYjoFfhBC4U9unU7.jpg', '{35,18,10749}', 'New York comedian Alvy Singer falls in love with the ditsy Annie Hall.', '[{"name": "Diane Keaton", "character": "Annie Hall"}, {"name": "Woody Allen", "character": "Alvy Singer"}, {"name": "Tony Roberts", "character": "Rob"}, {"name": "Carol Kane", "character": "Allison"}, {"name": "Paul Simon", "character": "Tony Lacey"}]', 'Woody Allen', NULL, '2026-07-13 21:31:52.033459');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (390, 'tt2082197', 127501, 'Barfi!', 2012, '/5cJIx2zKjDoUtPSliou23xsReb1.jpg', '{18,10749,35}', 'The heartwarming tale of Barfi, a charming deaf-mute young man from 1970s Darjeeling, and two unalike women who can''t help but fall for him.', '[{"name": "Ranbir Kapoor", "character": "Murphy Johnson \"Barfi\""}, {"name": "Priyanka Chopra Jonas", "character": "Jhilmil Chatterjee"}, {"name": "Ileana D''Cruz", "character": "Shruti Ghosh Sengupta"}, {"name": "Saurabh Shukla", "character": "Sub-Inspector Sudhanshu Dutta"}, {"name": "Jisshu Sengupta", "character": "Ranjit Sengupta"}]', 'Anurag Basu', NULL, '2026-07-13 21:31:52.603814');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (391, 'tt0060827', 797, 'Persona', 1966, '/fVA5hTcAOlW2LJyelViQfWHxUcx.jpg', '{18}', 'A young nurse, Alma, is put in charge of Elisabeth Vogler: an actress who is seemingly healthy in all respects, but will not talk. As they spend time together, Alma speaks to Elisabeth constantly, never receiving any answer.', '[{"name": "Bibi Andersson", "character": "Alma"}, {"name": "Liv Ullmann", "character": "Elisabet Vogler"}, {"name": "Margaretha Krook", "character": "The Doctor"}, {"name": "Gunnar Björnstrand", "character": "Herr Vogler"}, {"name": "Jörgen Lindström", "character": "Elisabet''s Son (uncredited)"}]', 'Ingmar Bergman', NULL, '2026-07-13 21:31:53.158221');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (392, 'tt0338564', 10775, 'Infernal Affairs', 2002, '/qdlwFWn2YdLzw5KHpMpzRY9BI7r.jpg', '{18,28,53,80,9648}', 'Chan Wing Yan, a young police officer, has been sent undercover as a mole in the local mafia. Lau Kin Ming, a young mafia member, infiltrates the police force. Years later, their older counterparts, Chen Wing Yan and Inspector Lau Kin Ming, respectively, race against time to expose the mole within their midst.', '[{"name": "Andy Lau", "character": "刘健明"}, {"name": "Tony Leung Chiu-wai", "character": "陈永仁"}, {"name": "Anthony Wong Chau-Sang", "character": "黄志诚"}, {"name": "Eric Tsang Chi-Wai", "character": "韩琛"}, {"name": "Kelly Chen Hui-Lin", "character": "李心儿"}]', 'Alan Mak Siu-Fai', NULL, '2026-07-13 21:31:53.723601');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (393, 'tt0871510', 14163, 'Chak De! India', 2007, '/mmFMgEsTRCAGAtwffGpuo3mJsxN.jpg', '{18}', 'A team of rag-tag girls with their own agenda form Team India competing for international fame in field hockey. Their coach, the ex-men''s Indian National team captain, returns from a life of shame after being unjustly accused of match fixing in his last match. Can he give the girls the motivation required to win, while dealing with the shadows of his own past?', '[{"name": "Shah Rukh Khan", "character": "Kabir Khan"}, {"name": "Vidya Malvade", "character": "Vidya Sharma"}, {"name": "Sagarika Ghatge", "character": "Preeti Sabarwal"}, {"name": "Shilpa Shukla", "character": "Bindia Naik"}, {"name": "Chitrashi Rawat", "character": "Komal Chautala"}]', 'Shimit Amin', NULL, '2026-07-13 21:31:54.302927');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (394, 'tt14849194', 840430, 'The Holdovers', 2023, '/VHSzNBTwxV8vh7wylo7O9CLdac.jpg', '{18,35}', 'A curmudgeonly instructor at a New England prep school is forced to remain on campus during Christmas break to babysit the handful of students with nowhere to go. Eventually, he forms an unlikely bond with one of them — a damaged, brainy troublemaker — and with the school’s head cook, who has just lost a son in Vietnam.', '[{"name": "Paul Giamatti", "character": "Paul Hunham"}, {"name": "Dominic Sessa", "character": "Angus Tully"}, {"name": "Da''Vine Joy Randolph", "character": "Mary Lamb"}, {"name": "Carrie Preston", "character": "Miss Lydia Crane"}, {"name": "Brady Hepner", "character": "Teddy Kountze"}]', 'Alexander Payne', NULL, '2026-07-13 21:31:54.861182');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (395, 'tt0053198', 147, 'The 400 Blows', 1959, '/12PuU23kkDLvTd0nb8hMlE3oShB.jpg', '{18}', 'For young Parisian boy Antoine Doinel, life is one difficult situation after another. Surrounded by inconsiderate adults, including his neglectful parents, Antoine spends his days with his best friend, Rene, trying to plan for a better life. When one of their schemes goes awry, Antoine ends up in trouble with the law, leading to even more conflicts with unsympathetic authority figures.', '[{"name": "Jean-Pierre Léaud", "character": "Antoine Doinel"}, {"name": "Claire Maurier", "character": "Gilberte Doinel"}, {"name": "Albert Rémy", "character": "Julien Doinel"}, {"name": "Georges Flamant", "character": "Mr. Bigey"}, {"name": "Patrick Auffay", "character": "René"}]', 'François Truffaut', NULL, '2026-07-13 21:31:55.424101');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (396, 'tt0108399', 319, 'True Romance', 1993, '/39lXk6ud6KiJgGbbWI2PUKS7y2.jpg', '{28,80,10749}', 'Clarence marries hooker Alabama, steals cocaine from her pimp, and tries to sell it in Hollywood, while the owners of the coke try to reclaim it.', '[{"name": "Christian Slater", "character": "Clarence Worley"}, {"name": "Patricia Arquette", "character": "Alabama Whitman"}, {"name": "Dennis Hopper", "character": "Clifford Worley"}, {"name": "Val Kilmer", "character": "Mentor"}, {"name": "Gary Oldman", "character": "Drexl Spivey"}]', 'Tony Scott', NULL, '2026-07-13 21:31:56.000982');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (397, 'tt12361178', 706872, 'Drishyam 2', 2021, '/8RJBCUGE27LX06tAES4jTELN0KA.jpg', '{53,80,18}', 'Seven years after the events of the first film, the family lives with the trauma from that fateful night. A gripping tale of an investigation and a family threatened by it. Will Georgekutty be able to protect his family this time?', '[{"name": "Mohanlal", "character": "Georgekutty"}, {"name": "Meena", "character": "Rani"}, {"name": "Murali Gopy", "character": "IG Thomas Bastin"}, {"name": "Asha Sarath", "character": "IG Geetha Prabhakar"}, {"name": "Siddique", "character": "Prabhakar"}]', 'Jeethu Joseph', NULL, '2026-07-13 21:31:56.57251');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (398, 'tt0056801', 422, '8½', 1963, '/23VIf7zNxAgaXwIlvzd3IvOd9sY.jpg', '{18}', 'Guido Anselmi, a film director, finds himself creatively barren at the peak of his career. Urged by his doctors to rest, Anselmi heads for a luxurious resort, but a sorry group gathers—his producer, staff, actors, wife, mistress, and relatives—each one begging him to get on with the show. In retreat from their dependency, he fantasizes about past women and dreams of his childhood.', '[{"name": "Marcello Mastroianni", "character": "Guido Anselmi"}, {"name": "Claudia Cardinale", "character": "Claudia"}, {"name": "Anouk Aimée", "character": "Luisa Anselmi"}, {"name": "Sandra Milo", "character": "Carla"}, {"name": "Rossella Falk", "character": "Rossella"}]', 'Federico Fellini', NULL, '2026-07-13 21:31:57.135426');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (399, 'tt0058461', 391, 'A Fistful of Dollars', 1964, '/lBwOEpwVeUAmrmglcstnaGcJq3Y.jpg', '{37}', 'The Man With No Name enters the Mexican village of San Miguel in the midst of a power struggle among the three Rojo brothers and sheriff John Baxter. When a regiment of Mexican soldiers bearing gold intended to pay for new weapons is waylaid by the Rojo brothers, the stranger inserts himself into the middle of the long-simmering battle, selling false information to both sides for his own benefit.', '[{"name": "Clint Eastwood", "character": "Joe"}, {"name": "Marianne Koch", "character": "Marisol"}, {"name": "Gian Maria Volonté", "character": "Ramón Rojo"}, {"name": "Wolfgang Lukschy", "character": "John Baxter"}, {"name": "Sieghardt Rupp", "character": "Esteban Rojo"}]', 'Sergio Leone', NULL, '2026-07-13 21:31:57.695573');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (400, 'tt0056217', 11697, 'The Man Who Shot Liberty Valance', 1962, '/4C1R0LEivLjbv3swAzJfzh0tzXl.jpg', '{37}', 'Questions arise when Senator Stoddard attends the funeral of a local man named Tom Doniphon in a small Western town. Flashing back, we learn Doniphon saved Stoddard, then a lawyer, when he was roughed up by a crew of outlaws terrorizing the town, led by Liberty Valance. As the territory''s safety hung in the balance, Doniphon and Stoddard, two of the only people standing up to him, proved to be very important, but different, foes to Valance.', '[{"name": "John Wayne", "character": "Tom Doniphon"}, {"name": "James Stewart", "character": "Ransom Stoddard"}, {"name": "Vera Miles", "character": "Hallie Stoddard"}, {"name": "Lee Marvin", "character": "Liberty Valance"}, {"name": "Edmond O''Brien", "character": "Dutton Peabody"}]', 'John Ford', NULL, '2026-07-13 21:31:58.254353');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (401, 'tt0106519', 6075, 'Carlito''s Way', 1993, '/g6D7mjQtndu768cusGmoEQY9fTB.jpg', '{80,18,53}', 'Free after years in prison, Carlito Brigante intends to give up his criminal ways, but it''s not long before the ex-con is sucked back into the New York City underworld.', '[{"name": "Al Pacino", "character": "Carlito Brigante"}, {"name": "Sean Penn", "character": "David Kleinfeld"}, {"name": "Penelope Ann Miller", "character": "Gail"}, {"name": "John Leguizamo", "character": "Benny Blanco"}, {"name": "Ingrid Rogers", "character": "Steffie"}]', 'Brian De Palma', NULL, '2026-07-13 21:31:58.854234');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (402, 'tt7775622', 515042, 'Free Solo', 2018, '/v4QfYZMACODlWul9doN9RxE99ag.jpg', '{99,12}', 'Follow Alex Honnold as he attempts to become the first person to ever free solo climb Yosemite''s 3,000 foot high El Capitan wall. With no ropes or safety gear, this would arguably be the greatest feat in rock climbing history.', '[{"name": "Alex Honnold", "character": "Self"}, {"name": "Tommy Caldwell", "character": "Self"}, {"name": "Jimmy Chin", "character": "Self"}, {"name": "Sanni McCandless", "character": "Self"}, {"name": "Mikey Schaefer", "character": "Self"}]', 'Jimmy Chin', NULL, '2026-07-13 21:31:59.417133');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (403, 'tt8613070', 531428, 'Portrait of a Lady on Fire', 2019, '/rUDuOKpkKBHxx41BScqKej72iT3.jpg', '{18,10749}', 'On an isolated island in Brittany at the end of the eighteenth century, a female painter is obliged to paint a wedding portrait of a young woman.', '[{"name": "Noémie Merlant", "character": "Marianne"}, {"name": "Adèle Haenel", "character": "Héloïse"}, {"name": "Luàna Bajrami", "character": "Sophie"}, {"name": "Valeria Golino", "character": "La Comtesse"}, {"name": "Christel Baras", "character": "La faiseuse d''ange"}]', 'Céline Sciamma', NULL, '2026-07-13 21:31:59.977414');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (404, 'tt39139925', 1582770, 'Dhurandhar: The Revenge', 2026, '/ptTwQES14pr5c3aZvJg56YlYgb1.jpg', '{28,80,53}', 'As rival gangs, corrupt officials and a ruthless Major Iqbal close in, Hamza''s mission for his country spirals into a bloody personal war where the line between patriot and monster disappears in the streets of Lyari.', '[{"name": "Ranveer Singh", "character": "Hamza Ali Mazari / Jaskirat Singh Rangi"}, {"name": "Arjun Rampal", "character": "Major Iqbal"}, {"name": "Rakesh Bedi", "character": "Jameel Jamali"}, {"name": "R. Madhavan", "character": "Ajay Sanyal"}, {"name": "Manav Gohil", "character": "Sushant Bansal"}]', 'Aditya Dhar', NULL, '2026-07-13 21:32:00.529569');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (405, 'tt1280558', 19703, 'A Wednesday!', 2008, '/gVUSxtJM3arL5VIUIRNYde20EF0.jpg', '{18,53}', 'Prakash Rathod, a retired police commissioner recounts the most memorable case of his career wherein he was informed about a bomb scare in Mumbai by an ordinary commoner.', '[{"name": "Anupam Kher", "character": "Prakash Rathod"}, {"name": "Naseeruddin Shah", "character": "The Anonymous Caller"}, {"name": "Jimmy Shergill", "character": "Arif Khan"}, {"name": "Deepal Shaw", "character": "Naina Roy"}, {"name": "Aamir Bashir", "character": "Jai Singh"}]', 'Neeraj Pandey', NULL, '2026-07-13 21:32:01.186732');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (406, 'tt0080455', 525, 'The Blues Brothers', 1980, '/rhYJKOt6UrQq7JQgLyQcSWW5R86.jpg', '{10402,35,80}', 'Jake Blues, just released from prison, puts his old band back together to save the Catholic home where he and his brother Elwood were raised.', '[{"name": "John Belushi", "character": "''Joliet'' Jake Blues"}, {"name": "Dan Aykroyd", "character": "Elwood Blues"}, {"name": "James Brown", "character": "Cleophus James"}, {"name": "Cab Calloway", "character": "Curtis"}, {"name": "Ray Charles", "character": "Ray"}]', 'John Landis', NULL, '2026-07-13 21:32:01.747442');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (407, 'tt0156887', 10494, 'Perfect Blue', 1997, '/6WTiOCfDPP8XV4jqfloiVWf7KHq.jpg', '{16,53}', 'Rising pop star Mima Kirigoe quits singing to pursue a career as an actress. After she takes up a role on a popular detective show, her handlers and collaborators begin turning up murdered. Harboring feelings of guilt and haunted by visions of her former self, Mima''s reality and fantasy meld into a frenzied paranoia.', '[{"name": "Junko Iwao", "character": "Mima Kirigoe (voice)"}, {"name": "Rica Matsumoto", "character": "Rumi (voice)"}, {"name": "Shiho Niiyama", "character": "Rei (voice)"}, {"name": "Masaaki Okura", "character": "Mamoru Uchida (voice)"}, {"name": "Shinpachi Tsuji", "character": "Tadokoro (voice)"}]', 'Satoshi Kon', NULL, '2026-07-13 21:32:02.310929');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (408, 'tt3915174', 315162, 'Puss in Boots: The Last Wish', 2022, '/kuf6dutpsT0vSVehic3EZIqkOBt.jpg', '{16,12,14,35,10751}', 'Puss in Boots discovers that his passion for adventure has taken its toll: He has burned through eight of his nine lives, leaving him with only one life left. Puss sets out on an epic journey to find the mythical Last Wish and restore his nine lives.', '[{"name": "Antonio Banderas", "character": "Puss in Boots (voice)"}, {"name": "Salma Hayek Pinault", "character": "Kitty Softpaws (voice)"}, {"name": "Harvey Guillén", "character": "Perrito (voice)"}, {"name": "Wagner Moura", "character": "Wolf (voice)"}, {"name": "Florence Pugh", "character": "Goldilocks (voice)"}]', 'Joel Crawford', NULL, '2026-07-13 21:32:02.887268');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (409, 'tt0861739', 7347, 'Elite Squad', 2007, '/lwIXz785N2fXi8hsBr1IXciFlkM.jpg', '{18,28,80}', 'In 1997, before the visit of the pope to Rio de Janeiro, Captain Nascimento from BOPE (Special Police Operations Battalion) is assigned to eliminate the risks of the drug dealers in a dangerous slum nearby where the pope intends to be lodged.', '[{"name": "Wagner Moura", "character": "Capitão Nascimento"}, {"name": "André Ramiro", "character": "André Matias"}, {"name": "Caio Junqueira", "character": "Neto"}, {"name": "Milhem Cortaz", "character": "Capitão Fabio"}, {"name": "Fernanda Machado", "character": "Maria"}]', 'José Padilha', NULL, '2026-07-13 21:32:03.450255');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (410, 'tt10431500', 637920, 'Miracle in Cell No. 7', 2019, '/bOth4QmNyEkalwahfPCfiXjNh1r.jpg', '{18}', 'Separated from his daughter, a father with an intellectual disability must prove his innocence when he is jailed for the death of a commander''s child.', '[{"name": "Aras Bulut İynemli", "character": "Memo"}, {"name": "Nisa Sofiya Aksongur", "character": "Ova"}, {"name": "İlker Aksum", "character": "Askorozlu"}, {"name": "Mesut Akusta", "character": "Yusuf"}, {"name": "Yıldıray Şahinler", "character": "Hafız"}]', 'Mehmet Ada Öztekin', NULL, '2026-07-13 21:32:04.013775');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (411, 'tt1877830', 414906, 'The Batman', 2022, '/74xTEgt7R36Fpooo50r9T25onhq.jpg', '{80,9648,53}', 'In his second year of fighting crime, Batman uncovers corruption in Gotham City that connects to his own family while facing a serial killer known as the Riddler.', '[{"name": "Robert Pattinson", "character": "Bruce Wayne / The Batman"}, {"name": "Zoë Kravitz", "character": "Selina Kyle"}, {"name": "Jeffrey Wright", "character": "Lt. James Gordon"}, {"name": "Colin Farrell", "character": "Oz / The Penguin"}, {"name": "Paul Dano", "character": "The Riddler"}]', 'Matt Reeves', NULL, '2026-07-13 21:32:04.730466');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (412, 'tt3498820', 271110, 'Captain America: Civil War', 2016, '/rAGiXaUfPzY7CDEyNKUofk3Kw2e.jpg', '{12,28,878}', 'Following the events of Age of Ultron, the collective governments of the world pass an act designed to regulate all superhuman activity. This polarizes opinion amongst the Avengers, causing two factions to side with Iron Man or Captain America, which causes an epic battle between former allies.', '[{"name": "Chris Evans", "character": "Steve Rogers / Captain America"}, {"name": "Robert Downey Jr.", "character": "Tony Stark / Iron Man"}, {"name": "Scarlett Johansson", "character": "Natasha Romanoff / Black Widow"}, {"name": "Sebastian Stan", "character": "Bucky Barnes / Winter Soldier"}, {"name": "Anthony Mackie", "character": "Sam Wilson / Falcon"}]', 'Joe Russo', NULL, '2026-07-13 21:32:05.388146');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (413, 'tt0903624', 49051, 'The Hobbit: An Unexpected Journey', 2012, '/yHA9Fc37VmpUA5UncTxxo3rTGVA.jpg', '{12,14,28}', 'Bilbo Baggins, a hobbit enjoying his quiet life, is swept into an epic quest by Gandalf the Grey and thirteen dwarves who seek to reclaim their mountain home from Smaug, the dragon.', '[{"name": "Martin Freeman", "character": "Bilbo Baggins"}, {"name": "Ian McKellen", "character": "Gandalf the Grey"}, {"name": "Richard Armitage", "character": "Thorin Oakenshield"}, {"name": "James Nesbitt", "character": "Bofur"}, {"name": "Ken Stott", "character": "Balin"}]', 'Peter Jackson', NULL, '2026-07-13 21:32:05.946723');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (424, 'tt0099785', 771, 'Home Alone', 1990, '/onTSipZ8R3bliBdKfPtsDuHTdlL.jpg', '{35,10751}', 'Eight-year-old Kevin McCallister makes the most of the situation after his family unwittingly leaves him behind when they go on Christmas vacation. When thieves try to break into his home, he puts up a fight like no other.', '[{"name": "Macaulay Culkin", "character": "Kevin"}, {"name": "Joe Pesci", "character": "Harry"}, {"name": "Daniel Stern", "character": "Marv"}, {"name": "John Heard", "character": "Peter"}, {"name": "Roberts Blossom", "character": "Marley"}]', 'Chris Columbus', NULL, '2026-07-13 21:32:12.47991');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (414, 'tt10280296', 598826, 'Sardar Udham', 2021, '/d4fpJXhUNukd5XnzRO1XfWf7v88.jpg', '{80,18,36}', 'A young Sardar Udham Singh left deeply scarred by the Jallianwala Bagh massacre, escaped into the mountains of Afghanistan, reaching London in 1933-34. Carrying an unhealed wound for 21 years, the revolutionary assassinated Michael O’Dwyer on 13th March, 1940, the man at the helm of affairs in Punjab, April 1919 to avenge the lost lives of his beloved brethren.', '[{"name": "Vicky Kaushal", "character": "Udham Singh"}, {"name": "Shaun Scott", "character": "Michael O''Dwyer"}, {"name": "Stephen Hogan", "character": "Detective Inspector John Swain"}, {"name": "Amol Parashar", "character": "Shaheed Bhagat Singh"}, {"name": "Kirsty Averton", "character": "Eileen Palmer"}]', 'Shoojit Sircar', NULL, '2026-07-13 21:32:06.501824');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (415, 'tt5052448', 419430, 'Get Out', 2017, '/tFXcEccSQMf3lfhfXKSU9iRBpa3.jpg', '{9648,53,27}', 'Chris and his girlfriend Rose go upstate to visit her parents for the weekend. At first, Chris reads the family''s overly accommodating behavior as nervous attempts to deal with their daughter''s interracial relationship, but as the weekend progresses, a series of increasingly disturbing discoveries lead him to a truth that he never could have imagined.', '[{"name": "Daniel Kaluuya", "character": "Chris Washington"}, {"name": "Allison Williams", "character": "Rose Armitage"}, {"name": "Catherine Keener", "character": "Missy Armitage"}, {"name": "Bradley Whitford", "character": "Dean Armitage"}, {"name": "Caleb Landry Jones", "character": "Jeremy Armitage"}]', 'Jordan Peele', NULL, '2026-07-13 21:32:07.075536');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (416, 'tt1285016', 37799, 'The Social Network', 2010, '/n0ybibhJtQ5icDqTp8eRytcIHJx.jpg', '{18}', 'In 2003, Harvard undergrad and computer programmer Mark Zuckerberg begins work on a new concept that eventually turns into the global social network known as Facebook. Six years later, Mark is one of the youngest billionaires ever, but his unprecedented success leads to both personal and legal complications when he ends up on the receiving end of two lawsuits, one involving his former friend.', '[{"name": "Jesse Eisenberg", "character": "Mark Zuckerberg"}, {"name": "Andrew Garfield", "character": "Eduardo Saverin"}, {"name": "Armie Hammer", "character": "Cameron Winklevoss / Tyler Winklevoss"}, {"name": "Justin Timberlake", "character": "Sean Parker"}, {"name": "Rooney Mara", "character": "Erica Albright"}]', 'David Fincher', NULL, '2026-07-13 21:32:07.70753');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (417, 'tt5013056', 374720, 'Dunkirk', 2017, '/b4Oe15CGLL61Ped0RAS9JpqdmCt.jpg', '{10752,28,18}', 'The story of the miraculous evacuation of Allied soldiers from Belgium, Britain, Canada and France, who were cut off and surrounded by the German army from the beaches and harbour of Dunkirk between May 26th and June 4th 1940 during World War II.', '[{"name": "Fionn Whitehead", "character": "Tommy"}, {"name": "Tom Hardy", "character": "Farrier"}, {"name": "Mark Rylance", "character": "Mr. Dawson"}, {"name": "Kenneth Branagh", "character": "Commander Bolton"}, {"name": "Cillian Murphy", "character": "Shivering Soldier"}]', 'Christopher Nolan', NULL, '2026-07-13 21:32:08.279784');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (418, 'tt1074638', 37724, 'Skyfall', 2012, '/d0IVecFQvsGdSbnMAHqiYsNYaJT.jpg', '{28,12,53}', 'When Bond''s latest assignment goes gravely wrong, agents around the world are exposed and MI6 headquarters is attacked. While M faces challenges to her authority and position from Gareth Mallory, the new Chairman of the Intelligence and Security Committee, it''s up to Bond, aided only by field agent Eve, to locate the mastermind behind the attack.', '[{"name": "Daniel Craig", "character": "James Bond"}, {"name": "Judi Dench", "character": "M"}, {"name": "Javier Bardem", "character": "Silva"}, {"name": "Ralph Fiennes", "character": "Gareth Mallory"}, {"name": "Naomie Harris", "character": "Eve"}]', 'Sam Mendes', NULL, '2026-07-13 21:32:08.873161');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (419, 'tt0780504', 64690, 'Drive', 2011, '/602vevIURmpDfzbnv5Ubi6wIkQm.jpg', '{18,53,80}', 'Driver is a skilled Hollywood stuntman who moonlights as a getaway driver for criminals. Though he projects an icy exterior, lately he''s been warming up to a pretty neighbor named Irene and her young son, Benicio. When Irene''s husband gets out of jail, he enlists Driver''s help in a million-dollar heist. The job goes horribly wrong, and Driver must risk his life to protect Irene and Benicio from the vengeful masterminds behind the robbery.', '[{"name": "Ryan Gosling", "character": "Driver"}, {"name": "Carey Mulligan", "character": "Irene"}, {"name": "Bryan Cranston", "character": "Shannon"}, {"name": "Albert Brooks", "character": "Bernie Rose"}, {"name": "Oscar Isaac", "character": "Standard"}]', 'Nicolas Winding Refn', NULL, '2026-07-13 21:32:09.419577');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (420, 'tt3748528', 330459, 'Rogue One: A Star Wars Story', 2016, '/i0yw1mFbB7sNGHCs7EXZPzFkdA1.jpg', '{28,12,878}', 'A rogue band of resistance fighters unite for a mission to steal the Death Star plans and bring a new hope to the galaxy.', '[{"name": "Felicity Jones", "character": "Jyn Erso"}, {"name": "Diego Luna", "character": "Cassian Andor"}, {"name": "Alan Tudyk", "character": "K-2SO"}, {"name": "Donnie Yen", "character": "Chirrut Imwe"}, {"name": "Jiang Wen", "character": "Baze Malbus"}]', 'Gareth Edwards', NULL, '2026-07-13 21:32:10.105796');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (421, 'tt1170358', 57158, 'The Hobbit: The Desolation of Smaug', 2013, '/xQYiXsheRCDBA39DOrmaw1aSpbk.jpg', '{14,12,28}', 'The Dwarves, Bilbo and Gandalf have successfully escaped the Misty Mountains, and Bilbo has gained the One Ring. They all continue their journey to get their gold back from the Dragon, Smaug.', '[{"name": "Ian McKellen", "character": "Gandalf the Grey"}, {"name": "Martin Freeman", "character": "Bilbo Baggins"}, {"name": "Richard Armitage", "character": "Thorin Oakenshield"}, {"name": "Benedict Cumberbatch", "character": "Smaug / Sauron"}, {"name": "Orlando Bloom", "character": "Legolas"}]', 'Peter Jackson', NULL, '2026-07-13 21:32:10.666633');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (422, 'tt2543472', 406997, 'Wonder', 2017, '/sONh3LYGFcVDTy8pm1tbSOB13Li.jpg', '{10751,18}', 'The story of August Pullman – a boy with facial differences – who enters fifth grade, attending a mainstream elementary school for the first time.', '[{"name": "Jacob Tremblay", "character": "Auggie"}, {"name": "Julia Roberts", "character": "Isabel"}, {"name": "Owen Wilson", "character": "Nate"}, {"name": "Izabela Vidovic", "character": "Via"}, {"name": "Noah Jupe", "character": "Jack Will"}]', 'Stephen Chbosky', NULL, '2026-07-13 21:32:11.220115');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (423, 'tt0421715', 4922, 'The Curious Case of Benjamin Button', 2008, '/26wEWZYt6yJkwRVkjcbwJEFh9IS.jpg', '{18,14,10749}', 'Born under unusual circumstances, Benjamin Button springs into being as an elderly man in a New Orleans nursing home and ages in reverse. Twelve years after his birth, he meets Daisy, a child who flits in and out of his life as she grows up to be a dancer. Though he has all sorts of unusual adventures over the course of his life, it is his relationship with Daisy, and the hope that they will come together at the right time, that drives Benjamin forward.', '[{"name": "Brad Pitt", "character": "Benjamin Button"}, {"name": "Cate Blanchett", "character": "Daisy Fuller"}, {"name": "Taraji P. Henson", "character": "Queenie"}, {"name": "Julia Ormond", "character": "Caroline Fuller"}, {"name": "Jason Flemyng", "character": "Thomas Button"}]', 'David Fincher', NULL, '2026-07-13 21:32:11.881797');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (426, 'tt0401383', 2013, 'The Diving Bell and the Butterfly', 2007, '/6NkJ4gnLrvLj0PZDW6sNM85JMbj.jpg', '{18,36}', 'Jean-Dominique Bauby, editor-in-chief of French fashion bible Elle magazine, has a devastating stroke at age 43. The damage to his brain stem results in locked-in syndrome, with which he is almost completely paralyzed and only able to communicate by blinking an eye. Bauby painstakingly dictates his memoir via the only means of expression left to him.', '[{"name": "Mathieu Amalric", "character": "Jean-Dominique Bauby"}, {"name": "Emmanuelle Seigner", "character": "Céline Desmoulins"}, {"name": "Marie-Josée Croze", "character": "Henriette Durand"}, {"name": "Anne Consigny", "character": "Claude"}, {"name": "Patrick Chesnais", "character": "Dr. Lepage"}]', 'Julian Schnabel', NULL, '2026-07-13 21:32:13.728771');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (427, 'tt0299977', 79, 'Hero', 2002, '/vxgZto2Cz7ILHAlmRXt50I2brB2.jpg', '{18,12,28,36}', 'During China''s Warring States period, a district prefect arrives at the palace of Qin Shi Huang, claiming to have killed the three assassins who had made an attempt on the king''s life three years ago.', '[{"name": "Jet Li", "character": "Nameless"}, {"name": "Tony Leung Chiu-wai", "character": "Broken Sword"}, {"name": "Maggie Cheung", "character": "Flying Snow"}, {"name": "Donnie Yen", "character": "Sky"}, {"name": "Zhang Ziyi", "character": "Moon"}]', 'Zhang Yimou', NULL, '2026-07-13 21:32:14.310462');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (428, 'tt0332280', 11036, 'The Notebook', 2004, '/rNzQyW4f8B8cQeg7Dgj3n6eT5k9.jpg', '{10749,18}', 'An epic love story centered around an older man who reads aloud to a woman with Alzheimer''s. From a faded notebook, the old man''s words bring to life the story about a couple who is separated by World War II, and is then passionately reunited, seven years later, after they have taken different paths.', '[{"name": "Ryan Gosling", "character": "Noah Calhoun"}, {"name": "Rachel McAdams", "character": "Allie Hamilton"}, {"name": "Gena Rowlands", "character": "Older Allie"}, {"name": "James Garner", "character": "Older Noah \"Duke\""}, {"name": "Joan Allen", "character": "Anne Hamilton"}]', 'Nick Cassavetes', NULL, '2026-07-13 21:32:14.88136');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (429, 'tt0162222', 8358, 'Cast Away', 2000, '/7lLJgKnAicAcR5UEuo8xhSMj18w.jpg', '{12,18}', 'Chuck Noland, a top international manager for FedEx, and Kelly, a Ph.D. student, are in love and heading towards marriage. Then Chuck''s plane to Malaysia crashes at sea during a terrible storm. He''s the only survivor, and finds himself marooned on a desolate island. With no way to escape, Chuck must find ways to survive in his new home.', '[{"name": "Tom Hanks", "character": "Chuck Noland"}, {"name": "Helen Hunt", "character": "Kelly Frears"}, {"name": "Nick Searcy", "character": "Stan"}, {"name": "Jenifer Lewis", "character": "Becca Twig"}, {"name": "Geoffrey Blake", "character": "Maynard Graham"}]', 'Robert Zemeckis', NULL, '2026-07-13 21:32:15.442282');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (430, 'tt2872718', 242582, 'Nightcrawler', 2014, '/j9HrX8f7GbZQm1BrBiR40uFQZSb.jpg', '{80,18,53}', 'When Lou Bloom, desperate for work, muscles into the world of L.A. crime journalism, he blurs the line between observer and participant to become the star of his own story. Aiding him in his effort is Nina, a TV-news veteran.', '[{"name": "Jake Gyllenhaal", "character": "Louis Bloom"}, {"name": "Rene Russo", "character": "Nina Romina"}, {"name": "Riz Ahmed", "character": "Rick"}, {"name": "Bill Paxton", "character": "Joe Loder"}, {"name": "Kevin Rahm", "character": "Frank Kruse"}]', 'Dan Gilroy', NULL, '2026-07-13 21:32:16.00464');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (431, 'tt0046438', 18148, 'Tokyo Story', 1953, '/g2YbTYKpY7N2yDSk7BfXZ18I5QV.jpg', '{18}', 'The elderly Shukishi and his wife, Tomi, take the long journey from their small seaside village to visit their adult children in Tokyo. Their elder son, Koichi, a doctor, and their daughter, Shige, a hairdresser, don''t have much time to spend with their aged parents, and so it falls to Noriko, the widow of their younger son who was killed in the war, to keep her in-laws company.', '[{"name": "Chishū Ryū", "character": "Shukichi Hirayama"}, {"name": "Chieko Higashiyama", "character": "Tomi Hirayama"}, {"name": "Setsuko Hara", "character": "Noriko Hirayama"}, {"name": "Haruko Sugimura", "character": "Shige Kaneko"}, {"name": "So Yamamura", "character": "Koichi Hirayama"}]', 'Yasujirō Ozu', NULL, '2026-07-13 21:32:16.579165');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (432, 'tt0365748', 747, 'Shaun of the Dead', 2004, '/dgXPhzNJH8HFTBjXPB177yNx6RI.jpg', '{27,35}', 'Shaun lives a supremely uneventful life, which revolves around his girlfriend, his mother, and, above all, his local pub. This gentle routine is threatened when the dead return to life and make strenuous attempts to snack on ordinary Londoners.', '[{"name": "Simon Pegg", "character": "Shaun"}, {"name": "Nick Frost", "character": "Ed"}, {"name": "Kate Ashfield", "character": "Liz"}, {"name": "Lucy Davis", "character": "Dianne"}, {"name": "Dylan Moran", "character": "David"}]', 'Edgar Wright', NULL, '2026-07-13 21:32:17.190768');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (433, 'tt2209418', 132344, 'Before Midnight', 2013, '/qbGKJmNUroDz75kh5Oafoall89e.jpg', '{10749,18}', 'It has been nine years since we last met Jesse and Celine, the French-American couple who once met on a train in Vienna. They now live in Paris with twin daughters but have spent a summer in Greece at the invitation of an author colleague of Jesse''s. When the vacation is over and Jesse must send his teenage son off to the States, he begins to question his life decisions, and his relationship with Celine is at risk.', '[{"name": "Ethan Hawke", "character": "Jesse"}, {"name": "Julie Delpy", "character": "Céline"}, {"name": "Seamus Davey-Fitzpatrick", "character": "Hank"}, {"name": "Jennifer Prior", "character": "Ella"}, {"name": "Charlotte Prior", "character": "Nina"}]', 'Richard Linklater', NULL, '2026-07-13 21:32:17.747746');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (434, 'tt0096874', 165, 'Back to the Future Part II', 1989, '/hQq8xZe5uLjFzSBt4LanNP7SQjl.jpg', '{12,35,878}', 'Marty and Doc are at it again as the time-traveling duo head to 2015 to nip some McFly family woes in the bud. But things go awry thanks to bully Biff Tannen and a pesky sports almanac. In a last-ditch attempt to set things straight, Marty finds himself bound for 1955 and face to face with his teenage parents -- again.', '[{"name": "Michael J. Fox", "character": "Marty McFly / Marty McFly Junior / Marlene McFly"}, {"name": "Christopher Lloyd", "character": "Doctor Emmett Brown"}, {"name": "Lea Thompson", "character": "Lorraine"}, {"name": "Thomas F. Wilson", "character": "Biff Tannen / Griff"}, {"name": "Elisabeth Shue", "character": "Jennifer"}]', 'Robert Zemeckis', NULL, '2026-07-13 21:32:18.337029');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (435, 'tt0258463', 2501, 'The Bourne Identity', 2002, '/aP8swke3gmowbkfZ6lmNidu0y9p.jpg', '{28,9648,53}', 'Wounded to the brink of death and suffering from amnesia, Jason Bourne is rescued at sea by a fisherman. With nothing to go on but a Swiss bank account number, he starts to reconstruct his life, but finds that many people he encounters want him dead. However, Bourne realizes that he has the combat and mental skills of a world-class spy—but who does he work for?', '[{"name": "Matt Damon", "character": "Jason Bourne"}, {"name": "Franka Potente", "character": "Marie Helena Kreutz"}, {"name": "Chris Cooper", "character": "Alexander Conklin"}, {"name": "Clive Owen", "character": "The Professor"}, {"name": "Brian Cox", "character": "Ward Abbott"}]', 'Doug Liman', NULL, '2026-07-13 21:32:18.924142');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (436, 'tt0169858', 18491, 'Neon Genesis Evangelion: The End of Evangelion', 1997, '/j6G24dqI4WgUtChhWjfnI4lnmiK.jpg', '{16,878,18,14,28}', 'SEELE orders an all-out attack on NERV, aiming to destroy the Evas before Gendo can advance his own plans for the Human Instrumentality Project. Shinji is pushed to the limits of his sanity as he is forced to decide the fate of humanity.', '[{"name": "Megumi Ogata", "character": "Shinji Ikari (voice)"}, {"name": "Megumi Hayashibara", "character": "Rei Ayanami / Yui Ikari (voice)"}, {"name": "Kotono Mitsuishi", "character": "Misato Katsuragi (voice)"}, {"name": "Yuko Miyamura", "character": "Asuka Langley Soryu (voice)"}, {"name": "Fumihiko Tachiki", "character": "Gendo Ikari (voice)"}]', 'Kazuya Tsurumaki', NULL, '2026-07-13 21:32:19.504549');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (437, 'tt0166896', 404, 'The Straight Story', 1999, '/tT9cMiVDdtlcdZxOoFy3VRmEoKk.jpg', '{18}', 'Retired farmer and widower Alvin Straight learns one day that his distant brother Lyle has suffered a stroke and may not recover. Alvin is determined to make things right with Lyle while he still can, but his brother lives in Wisconsin, while Alvin is stuck in Iowa with no car and no driver''s license. He then has the idea of making the trip on his old lawnmower, thus beginning a picturesque and at times deeply spiritual odyssey.', '[{"name": "Richard Farnsworth", "character": "Alvin"}, {"name": "Sissy Spacek", "character": "Rose"}, {"name": "Jane Galloway Heitz", "character": "Dorothy"}, {"name": "Joseph A. Carpenter", "character": "Bud"}, {"name": "Donald Wiegert", "character": "Sig"}]', 'David Lynch', NULL, '2026-07-13 21:32:20.164081');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (438, 'tt0048424', 3112, 'The Night of the Hunter', 1955, '/rBka0nFWiHxabHRLr0KfIA8Yiaq.jpg', '{80,18,53}', 'In Depression-era West Virginia, a serial-killing preacher hunts two young children who know the whereabouts of a stash of money.', '[{"name": "Robert Mitchum", "character": "Preacher Harry Powell"}, {"name": "Shelley Winters", "character": "Willa Harper"}, {"name": "Lillian Gish", "character": "Rachel Cooper"}, {"name": "Billy Chapin", "character": "John Harper"}, {"name": "Sally Jane Bruce", "character": "Pearl Harper"}]', 'Charles Laughton', NULL, '2026-07-13 21:32:20.829196');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (439, 'tt2545118', 158999, 'Blackfish', 2013, '/kCk4mDFE96Mn1AYfEcbxkIiw7ND.jpg', '{99}', 'Notorious killer whale Tilikum is responsible for the deaths of three individuals, including a top killer whale trainer. Blackfish shows the sometimes devastating consequences of keeping such intelligent and sentient creatures in captivity.', '[{"name": "Dean Gomersall", "character": "Self"}, {"name": "Samantha Berg", "character": "Self"}, {"name": "John Jett", "character": "Self"}, {"name": "John Hargrove", "character": "Self"}, {"name": "Carol Ray", "character": "Self"}]', 'Gabriela Cowperthwaite', NULL, '2026-07-13 21:32:21.387159');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (440, 'tt0425112', 4638, 'Hot Fuzz', 2007, '/zPib4ukTSdXvHP9pxGkFCe34f3y.jpg', '{80,28,35}', 'Former London constable Nicholas Angel finds it difficult to adapt to his new assignment in the sleepy British village of Sandford. Not only does he miss the excitement of the big city, but he also has a well-meaning oaf for a partner. However, when a series of grisly accidents rocks Sandford, Angel smells something rotten in the idyllic village.', '[{"name": "Simon Pegg", "character": "Nicholas Angel"}, {"name": "Nick Frost", "character": "PC Danny Butterman"}, {"name": "Jim Broadbent", "character": "Inspector Frank Butterman"}, {"name": "Paddy Considine", "character": "DS Andy Wainwright"}, {"name": "Rafe Spall", "character": "DC Andy Cartwright"}]', 'Edgar Wright', NULL, '2026-07-13 21:32:21.982878');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (441, 'tt0099487', 162, 'Edward Scissorhands', 1990, '/e0FqKFvGPdQNWG8tF9cZBtev9Em.jpg', '{14,18,10749}', 'A small suburban town receives a visit from a castaway unfinished science experiment named Edward.', '[{"name": "Johnny Depp", "character": "Edward Scissorhands"}, {"name": "Winona Ryder", "character": "Kim"}, {"name": "Dianne Wiest", "character": "Peg"}, {"name": "Anthony Michael Hall", "character": "Jim"}, {"name": "Kathy Baker", "character": "Joyce"}]', 'Tim Burton', NULL, '2026-07-13 21:32:22.592178');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (442, 'tt0036868', 887, 'The Best Years of Our Lives', 1946, '/gd5EoAU4MM57sW3vlWxJ0NMM8cV.jpg', '{18,10749,10752}', 'It''s the hope that sustains the spirit of every GI: the dream of the day when he will finally return home. For three WWII veterans, the day has arrived. But for each man, the dream is about to become a nightmare.', '[{"name": "Dana Andrews", "character": "Fred Derry"}, {"name": "Fredric March", "character": "Al Stephenson"}, {"name": "Harold Russell", "character": "Homer Parrish"}, {"name": "Teresa Wright", "character": "Peggy Stephenson"}, {"name": "Myrna Loy", "character": "Milly Stephenson"}]', 'William Wyler', NULL, '2026-07-13 21:32:23.158636');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (443, 'tt0449059', 773, 'Little Miss Sunshine', 2006, '/niNdhTpPHSgw22tK0PLjQMV640v.jpg', '{35,18}', 'A family loaded with quirky, colorful characters piles into an old van and road trips to California for little Olive to compete in a beauty pageant.', '[{"name": "Greg Kinnear", "character": "Richard Hoover"}, {"name": "Toni Collette", "character": "Sheryl Hoover"}, {"name": "Steve Carell", "character": "Frank Ginsberg"}, {"name": "Paul Dano", "character": "Dwayne Hoover"}, {"name": "Abigail Breslin", "character": "Olive Hoover"}]', 'Jonathan Dayton', NULL, '2026-07-13 21:32:23.722788');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (444, 'tt2245084', 177572, 'Big Hero 6', 2014, '/2mxS4wUimwlLmI1xp6QW6NSU361.jpg', '{12,10751,16,28,35}', 'A special bond develops between plus-sized inflatable robot Baymax, and prodigy Hiro Hamada, who team up with a group of friends to form a band of high-tech heroes.', '[{"name": "Scott Adsit", "character": "Baymax (voice)"}, {"name": "Ryan Potter", "character": "Hiro Hamada (voice)"}, {"name": "Daniel Henney", "character": "Tadashi Hamada (voice)"}, {"name": "T.J. Miller", "character": "Fred (voice)"}, {"name": "Jamie Chung", "character": "GoGo Tomago (voice)"}]', 'Don Hall', NULL, '2026-07-13 21:32:24.274353');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (445, 'tt0085334', 850, 'A Christmas Story', 1983, '/34nSHYqmb7222tiqiuKqKJmZiQa.jpg', '{35,10751}', 'The comic mishaps and adventures of a young boy named Ralph, trying to convince his parents, teachers, and Santa that a Red Ryder B.B. gun really is the perfect Christmas gift for the 1940s.', '[{"name": "Melinda Dillon", "character": "Mother"}, {"name": "Darren McGavin", "character": "The Old Man"}, {"name": "Peter Billingsley", "character": "Ralphie"}, {"name": "Jean Shepherd", "character": "Ralphie as an Adult (voice)"}, {"name": "Ian Petrella", "character": "Randy"}]', 'Bob Clark', NULL, '2026-07-13 21:32:24.848634');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (465, 'tt0046911', 827, 'Diabolique', 1955, '/jE8ygUYBUGyUcM4sR6iinPqYeDK.jpg', '{53,9648}', 'The cruel and abusive headmaster of a boarding school, Michel Delassalle, is murdered by an unlikely duo -- his meek wife and the mistress he brazenly flaunts. The women become increasingly unhinged by a series of odd occurrences after Delassalle''s corpse mysteriously disappears.', '[{"name": "Véra Clouzot", "character": "Christina Delassalle"}, {"name": "Simone Signoret", "character": "Nicole Horner"}, {"name": "Paul Meurisse", "character": "Michel Delassalle"}, {"name": "Charles Vanel", "character": "Police Inspector Alfred Fichet"}, {"name": "Jean Brochard", "character": "Plantiveau"}]', 'Henri-Georges Clouzot', NULL, '2026-07-13 21:32:36.217733');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (446, 'tt0058946', 17295, 'The Battle of Algiers', 1966, '/2p3AFtOHFvP6OeVMqlnL1zLKOqL.jpg', '{18,10752,36}', 'Paratrooper commander Colonel Mathieu, a former French Resistance fighter during World War II, is sent to Algeria to reinforce efforts to squelch the uprisings of the Algerian War. There he faces Ali la Pointe, a former petty criminal who, as the leader of the Algerian Front de Liberation Nationale, directs terror strategies against the colonial French government occupation. As each side resorts to ever-increasing brutality, no violent act is too unthinkable.', '[{"name": "Brahim Hadjadj", "character": "Ali La Pointe"}, {"name": "Mohamed Ben Kassen", "character": "Petit Omar"}, {"name": "Yacef Saâdi", "character": "El-Hadi Jaffar"}, {"name": "Fouzia El Kader", "character": "Halima"}, {"name": "Hadj Smaine Mohamed Seghir"}]', 'Gillo Pontecorvo', NULL, '2026-07-13 21:32:25.422817');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (447, 'tt1596363', 318846, 'The Big Short', 2015, '/scVEaJEwP8zUix8vgmMoJJ9Nq0w.jpg', '{35,18}', 'The men who made millions from a global economic meltdown.', '[{"name": "Steve Carell", "character": "Mark Baum"}, {"name": "Christian Bale", "character": "Michael Burry"}, {"name": "Ryan Gosling", "character": "Jared Vennett"}, {"name": "Brad Pitt", "character": "Ben Rickert"}, {"name": "Marisa Tomei", "character": "Cynthia Baum"}]', 'Adam McKay', NULL, '2026-07-13 21:32:25.97394');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (448, 'tt0808417', 2011, 'Persepolis', 2007, '/aU8i2QAdTyRR1nYb36Gq51xXP8p.jpg', '{16,18}', 'In 1970s Iran, Marjane ''Marji'' Satrapi watches events through her young eyes and her idealistic family of a long dream being fulfilled of the hated Shah''s defeat in the Iranian Revolution of 1979. However as Marji grows up, she witnesses first hand how the new Iran, now ruled by Islamic fundamentalists, has become a repressive tyranny on its own.', '[{"name": "Chiara Mastroianni", "character": "Marjane (voice)"}, {"name": "Danielle Darrieux", "character": "Marjane''s Grandmother (voice)"}, {"name": "Catherine Deneuve", "character": "Marjane''s Mother (voice)"}, {"name": "Simon Abkarian", "character": "Marjane''s Father (voice)"}, {"name": "Gabrielle Lopes Benites", "character": "Young Marjane (voice)"}]', 'Marjane Satrapi', NULL, '2026-07-13 21:32:26.529363');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (449, 'tt1568346', 65754, 'The Girl with the Dragon Tattoo', 2011, '/8bokS83zGdhaXgN9tjidUKmAftW.jpg', '{53,80,9648}', 'Disgraced journalist Mikael Blomkvist investigates the disappearance of a weary patriarch''s niece from 40 years ago. He is aided by the pierced, tattooed, punk computer hacker named Lisbeth Salander. As they work together in the investigation, Blomkvist and Salander uncover immense corruption beyond anything they have ever imagined.', '[{"name": "Daniel Craig", "character": "Mikael Blomkvist"}, {"name": "Rooney Mara", "character": "Lisbeth Salander"}, {"name": "Christopher Plummer", "character": "Henrik Vanger"}, {"name": "Stellan Skarsgård", "character": "Martin Vanger"}, {"name": "Robin Wright", "character": "Erika Berger"}]', 'David Fincher', NULL, '2026-07-13 21:32:27.095872');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (450, 'tt0116231', 26900, 'The Bandit', 1996, '/44KTRoayojxpzti2okBZGKmjEGM.jpg', '{80,18,53}', 'The film tells the story of a group of bandits captured in the Cudi Mountains 35 years ago. All of them have died, either from illness or vendettas; only Baran (Şener Şen) survives. After serving his 35-year sentence, Baran is released from Viranşehir Prison and learns that his birthplace is now submerged under the waters of a dam. Ceren Ana (Zübeyde Erden) tells him about the past. Baran is imprisoned because of the betrayal of his old friend Berfo (Kamran Usluer). Berfo stole the bandits gold, bought his childhood love Keje (Sermin Hürmeriç) from her father, and fled to Istanbul. While Baran is searching for Keje, he encounters a young man named Cumali (Uğur Yücel). These two men find solace in each other to avoid being swept away by the storms of the big city. And in this world where violence, betrayal, passion, boundless love and hatred intertwine, they try to survive.', '[{"name": "Şener Şen", "character": "Baran"}, {"name": "Uğur Yücel", "character": "Cumali"}, {"name": "Sermin Hürmeriç", "character": "Keje"}, {"name": "Yeşim Salkım", "character": "Emel"}, {"name": "Kamran Usluer", "character": "Mahmut Şahoğlu/Berfo"}]', 'Yavuz Turgul', NULL, '2026-07-13 21:32:27.655122');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (451, 'tt1535109', 109424, 'Captain Phillips', 2013, '/8Td0kkocW6sD3uRpzwfMfkqMWhx.jpg', '{28,18,53}', 'The true story of Captain Richard Phillips and the 2009 hijacking by Somali pirates of the US-flagged MV Maersk Alabama, the first American cargo ship to be hijacked in two hundred years.', '[{"name": "Tom Hanks", "character": "Captain Richard Phillips"}, {"name": "Barkhad Abdi", "character": "Muse"}, {"name": "Barkhad Abdirahman", "character": "Bilal"}, {"name": "Faysal  Ahmed", "character": "Najee"}, {"name": "Mahat M. Ali", "character": "Elmi"}]', 'Paul Greengrass', NULL, '2026-07-13 21:32:28.22016');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (452, 'tt0139654', 2034, 'Training Day', 2001, '/bUeiwBQdupBLQthMCHKV7zv56uv.jpg', '{28,80,18}', 'On his first day on the job as a narcotics officer, a rookie cop works with a rogue detective who isn''t what he appears.', '[{"name": "Denzel Washington", "character": "Alonzo"}, {"name": "Ethan Hawke", "character": "Jake"}, {"name": "Scott Glenn", "character": "Roger"}, {"name": "Tom Berenger", "character": "Stan Gursky"}, {"name": "Harris Yulin", "character": "Doug Rosselli"}]', 'Antoine Fuqua', NULL, '2026-07-13 21:32:28.77812');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (453, 'tt0113568', 9323, 'Ghost in the Shell', 1995, '/9gC88zYUBARRSThcG93MvW14sqx.jpg', '{28,16,878}', 'In the year 2029, the barriers of our world have been broken down by the net and by cybernetics, but this brings new vulnerability to humans in the form of brain-hacking. When a highly-wanted hacker known as ''The Puppetmaster'' begins involving them in politics, Section 9, a group of cybernetically enhanced cops, are called in to investigate and stop the Puppetmaster.', '[{"name": "Atsuko Tanaka", "character": "Motoko Kusanagi (voice)"}, {"name": "Akio Otsuka", "character": "Batou (voice)"}, {"name": "Iemasa Kayumi", "character": "Puppetmaster (voice)"}, {"name": "Koichi Yamadera", "character": "Togusa (voice)"}, {"name": "Yutaka Nakano", "character": "Ishikawa (voice)"}]', 'Mamoru Oshii', NULL, '2026-07-13 21:32:29.337991');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (454, 'tt0033870', 963, 'The Maltese Falcon', 1941, '/bf4o6Uzw5wqLjdKwRuiDrN1xyvl.jpg', '{9648,80,53}', 'A private detective takes on a case that involves him with three eccentric criminals, a beautiful liar, and their quest for a priceless statuette.', '[{"name": "Humphrey Bogart", "character": "Samuel Spade"}, {"name": "Mary Astor", "character": "Brigid O''Shaughnessy"}, {"name": "Gladys George", "character": "Iva Archer"}, {"name": "Peter Lorre", "character": "Joel Cairo"}, {"name": "Barton MacLane", "character": "Lt. of Detectives Dundy"}]', 'John Huston', NULL, '2026-07-13 21:32:29.916966');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (466, 'tt0040746', 1580, 'Rope', 1948, '/9ar6rxLDB8kagAnXZKn6h9smscr.jpg', '{53,80,18}', 'Two young men attempt to prove they committed the perfect murder by hosting a dinner party for the family of a classmate they just strangled to death.', '[{"name": "James Stewart", "character": "Rupert Cadell"}, {"name": "John Dall", "character": "Brandon Shaw"}, {"name": "Farley Granger", "character": "Phillip Morgan"}, {"name": "Cedric Hardwicke", "character": "Mr. Henry Kentley"}, {"name": "Constance Collier", "character": "Mrs. Anita Atwater"}]', 'Alfred Hitchcock', NULL, '2026-07-13 21:32:36.785153');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (455, 'tt0325710', 616, 'The Last Samurai', 2003, '/a8jmJPs5eZBARmnuEEvZwbjwyz4.jpg', '{18,28,10752}', 'Nathan Algren is an American hired to instruct the Japanese army in the ways of modern warfare, which finds him learning to respect the samurai and the honorable principles that rule them. Pressed to destroy the samurai''s way of life in the name of modernization and open trade, Algren decides to become an ultimate warrior himself and to fight for their right to exist.', '[{"name": "Tom Cruise", "character": "Nathan Algren"}, {"name": "Ken Watanabe", "character": "Moritsugu Katsumoto"}, {"name": "Timothy Spall", "character": "Simon Graham"}, {"name": "Tony Goldwyn", "character": "Col. Benjamin Bagley"}, {"name": "Hiroyuki Sanada", "character": "Ujio"}]', 'Edward Zwick', NULL, '2026-07-13 21:32:30.495962');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (456, 'tt0093773', 106, 'Predator', 1987, '/aN3cdjIK70KGmD84et8MMblU87Q.jpg', '{878,28,12,53}', 'A team of elite commandos on a secret mission in a Central American jungle come to find themselves hunted by an extraterrestrial warrior.', '[{"name": "Arnold Schwarzenegger", "character": "Major Alan \"Dutch\" Schaefer"}, {"name": "Carl Weathers", "character": "Al Dillon"}, {"name": "Kevin Peter Hall", "character": "The Predator / Helicopter Pilot"}, {"name": "Elpidia Carrillo", "character": "Anna Gonsalves"}, {"name": "Bill Duke", "character": "Mac Eliot"}]', 'John McTiernan', NULL, '2026-07-13 21:32:31.048373');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (457, 'tt0117666', 12498, 'Sling Blade', 1996, '/rioWUWXPFNSjwm9NO2aau9x0wlP.jpg', '{18}', 'Karl Childers, a mentally disabled man, has been in the custody of the state mental hospital since the age of 12 for killing his mother and her lover. Although thoroughly institutionalized, he is deemed fit to be released into the outside world.', '[{"name": "Billy Bob Thornton", "character": "Karl Childers"}, {"name": "Dwight Yoakam", "character": "Doyle Hargraves"}, {"name": "J.T. Walsh", "character": "Charles Bushman"}, {"name": "John Ritter", "character": "Vaughan Cunningham"}, {"name": "Lucas Black", "character": "Frank Wheatley"}]', 'Billy Bob Thornton', NULL, '2026-07-13 21:32:31.61501');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (458, 'tt0765429', 4982, 'American Gangster', 2007, '/sX9idXDqRUxE5ffww3n3RV5gL55.jpg', '{18,80}', 'Loosely based on the criminal career of Frank Lucas, a gangster from La Grange, North Carolina, who smuggled heroin into the United States on American service planes returning from the Vietnam War, before being detained by a task force led by Newark Detective Richie Roberts.', '[{"name": "Denzel Washington", "character": "Frank Lucas"}, {"name": "Russell Crowe", "character": "Richie Roberts"}, {"name": "Josh Brolin", "character": "Detective Trupo"}, {"name": "Chiwetel Ejiofor", "character": "Huey Lucas"}, {"name": "Cuba Gooding Jr.", "character": "Nicky Barnes"}]', 'Ridley Scott', NULL, '2026-07-13 21:32:32.175379');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (459, 'tt0087332', 620, 'Ghostbusters', 1984, '/7E8nLijS9AwwUEPu2oFYOVKhdFA.jpg', '{35,14}', 'After losing their university jobs, three parapsychologists start a ghost-catching business in New York City and uncover a supernatural threat that could destroy the world.', '[{"name": "Bill Murray", "character": "Peter Venkman"}, {"name": "Dan Aykroyd", "character": "Ray Stantz"}, {"name": "Sigourney Weaver", "character": "Dana Barrett"}, {"name": "Harold Ramis", "character": "Egon Spengler"}, {"name": "Rick Moranis", "character": "Louis Tully"}]', 'Ivan Reitman', NULL, '2026-07-13 21:32:32.733835');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (460, 'tt1302006', 398978, 'The Irishman', 2019, '/mbm8k3GFhXS0ROd9AD1gqYbIFbM.jpg', '{80,18,36}', 'Pennsylvania, 1956. Frank Sheeran, a war veteran of Irish origin who works as a truck driver, accidentally meets mobster Russell Bufalino. Once Frank becomes his trusted man, Bufalino sends him to Chicago with the task of helping Jimmy Hoffa, a powerful union leader related to organized crime, with whom Frank will maintain a close friendship for nearly twenty years.', '[{"name": "Robert De Niro", "character": "Frank Sheeran"}, {"name": "Al Pacino", "character": "Jimmy Hoffa"}, {"name": "Joe Pesci", "character": "Russell Bufalino"}, {"name": "Harvey Keitel", "character": "Angelo Bruno"}, {"name": "Ray Romano", "character": "Bill Bufalino"}]', 'Martin Scorsese', NULL, '2026-07-13 21:32:33.395508');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (461, 'tt0088847', 2108, 'The Breakfast Club', 1985, '/gp4zlj7wgbiofLMNsTPndMuO3PN.jpg', '{35,18}', 'Five high school students from different walks of life endure a Saturday detention under a power-hungry principal. The disparate group includes rebel John, princess Claire, outcast Allison, brainy Brian and Andrew, the jock. Each has a chance to tell his or her story, making the others see them a little differently -- and when the day ends, they question whether school will ever be the same.', '[{"name": "Emilio Estevez", "character": "Andrew Clark"}, {"name": "Judd Nelson", "character": "John Bender"}, {"name": "Molly Ringwald", "character": "Claire Standish"}, {"name": "Anthony Michael Hall", "character": "Brian Johnson"}, {"name": "Ally Sheedy", "character": "Allison Reynolds"}]', 'John Hughes', NULL, '2026-07-13 21:32:33.96511');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (462, 'tt0046268', 204, 'The Wages of Fear', 1953, '/sNOvIp4X0fmCMfgEs2ww5IyMgFm.jpg', '{18,53,12}', 'In a run-down South American town, four men are paid to drive trucks loaded with nitroglycerin into the jungle through to the oil field. Friendships are tested and rivalries develop as they embark upon the perilous journey.', '[{"name": "Yves Montand", "character": "Mario Livi"}, {"name": "Charles Vanel", "character": "Mr. Jo"}, {"name": "Peter van Eyck", "character": "Bimba"}, {"name": "Folco Lulli", "character": "Luigi"}, {"name": "Véra Clouzot", "character": "Linda"}]', 'Henri-Georges Clouzot', NULL, '2026-07-13 21:32:34.527658');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (463, 'tt0770802', 89708, 'Samsara', 2011, '/qodkea4k0pNUmNTl5TJO2PdTqgW.jpg', '{99}', 'Filmed over nearly five years in twenty-five countries on five continents, and shot on seventy-millimetre film, Samsara transports us to the varied worlds of sacred grounds, disaster zones, industrial complexes, and natural wonders.', '[{"name": "Ni Made Megahadi Pratiwi", "character": "Dancer: Valinese Tari Legong Dancers, Indonesia"}, {"name": "Puti Sri Candra Dewi", "character": "Dancer: Valinese Tari Legong Dancers, Indonesia"}, {"name": "Putu Dinda Pratika", "character": "Dancer: Valinese Tari Legong Dancers, Indonesia"}, {"name": "Marcos Luna", "character": "Tattoo Daddy: USA"}, {"name": "Hiroshi Ishiguro", "character": "Professor and Robot Clone: Japan"}]', 'Ron Fricke', NULL, '2026-07-13 21:32:35.083142');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (464, 'tt8367814', 522627, 'The Gentlemen', 2019, '/jtrhTYB7xSrJxR1vusu99nvnZ1g.jpg', '{28,35,80}', 'American expat Mickey Pearson has built a highly profitable marijuana empire in London. When word gets out that he’s looking to cash out of the business forever it triggers plots, schemes, bribery and blackmail in an attempt to steal his domain out from under him.', '[{"name": "Matthew McConaughey", "character": "Michael Pearson"}, {"name": "Charlie Hunnam", "character": "Ray"}, {"name": "Michelle Dockery", "character": "Rosalind Pearson"}, {"name": "Jeremy Strong", "character": "Matthew"}, {"name": "Lyne Renee", "character": "Jackie"}]', 'Guy Ritchie', NULL, '2026-07-13 21:32:35.66201');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (467, 'tt2194499', 122906, 'About Time', 2013, '/ls6zswrOZVhCXQBh96DlbnLBajM.jpg', '{18,10749,14}', 'The night after another unsatisfactory New Year''s party, Tim''s father reveals to him that the men in their family have the ability to travel through time. They can''t change history, but they can change what happens and has happened in their own lives. Thus begins the start of a lesson in learning to appreciate life itself as it is, as it comes, and most importantly, the people living alongside us.', '[{"name": "Domhnall Gleeson", "character": "Tim Lake"}, {"name": "Rachel McAdams", "character": "Mary"}, {"name": "Bill Nighy", "character": "Dad"}, {"name": "Tom Hollander", "character": "Harry"}, {"name": "Margot Robbie", "character": "Charlotte"}]', 'Richard Curtis', NULL, '2026-07-13 21:32:37.361999');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (468, 'tt0154420', 309, 'The Celebration', 1998, '/2LRzNq41yrY8EjCnD1S8sCCPvKk.jpg', '{18}', 'The family of a wealthy businessman gather to celebrate his 60th birthday. During the course of the party, his eldest son presents a speech that reveals a devastating secret that turns the night into a battle of truth and denial.', '[{"name": "Ulrich Thomsen", "character": "Christian"}, {"name": "Henning Moritzen", "character": "Faderen"}, {"name": "Thomas Bo Larsen", "character": "Michael"}, {"name": "Paprika Steen", "character": "Helene"}, {"name": "Birthe Neumann", "character": "Moderen"}]', 'Thomas Vinterberg', NULL, '2026-07-13 21:32:37.959553');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (469, 'tt0020629', 143, 'All Quiet on the Western Front', 1930, '/1wZUB08igw8iLUgF1r4T6aJD65b.jpg', '{18,10752}', 'When a group of idealistic young men join the German Army during the Great War, they are assigned to the Western Front, where their patriotism is destroyed by the harsh realities of combat.', '[{"name": "Louis Wolheim", "character": "Stanislaus ''Kat'' Katczinsky"}, {"name": "Lew Ayres", "character": "Paul Bäumer"}, {"name": "John Wray", "character": "Himmelstoss"}, {"name": "Arnold Lucy", "character": "Kantorek"}, {"name": "Ben Alexander", "character": "Franz Kemmerich"}]', 'Lewis Milestone', NULL, '2026-07-13 21:32:38.539264');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (470, 'tt0091042', 9377, 'Ferris Bueller''s Day Off', 1986, '/9LTQNCvoLsKXP0LtaKAaYVtRaQL.jpg', '{35}', 'After high school slacker Ferris Bueller successfully fakes an illness in order to skip school for the day, he goes on a series of adventures throughout Chicago with his girlfriend Sloane and best friend Cameron, all the while trying to outwit his wily school principal and fed-up sister.', '[{"name": "Matthew Broderick", "character": "Ferris Bueller"}, {"name": "Alan Ruck", "character": "Cameron Frye"}, {"name": "Mia Sara", "character": "Sloane Peterson"}, {"name": "Jeffrey Jones", "character": "Ed Rooney"}, {"name": "Jennifer Grey", "character": "Jeanie Bueller"}]', 'John Hughes', NULL, '2026-07-13 21:32:39.106501');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (471, 'tt0088258', 11031, 'This Is Spinal Tap', 1984, '/b3lllDltoBws5uKZzBYVSjpjjJx.jpg', '{35,10402}', '"This Is Spinal Tap" shines a light on the self-contained universe of a metal band struggling to get back on the charts, including everything from its complicated history of ups and downs, gold albums, name changes and undersold concert dates, along with the full host of requisite groupies, promoters, hangers-on and historians, sessions, release events and those special behind-the-scenes moments that keep it all real.', '[{"name": "Christopher Guest", "character": "Nigel Tufnel"}, {"name": "Michael McKean", "character": "David St. Hubbins"}, {"name": "Harry Shearer", "character": "Derek Smalls"}, {"name": "Rob Reiner", "character": "Marty DiBergi"}, {"name": "June Chadwick", "character": "Jeanine Pettibone"}]', 'Rob Reiner', NULL, '2026-07-13 21:32:39.66574');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (472, 'tt12888462', 682110, 'My Octopus Teacher', 2020, '/hvTVZb7hBC8tZAGoEhH5eiMJu2B.jpg', '{99}', 'After years of swimming every day in the freezing ocean at the tip of Africa, Craig Foster meets an unlikely teacher: a young octopus who displays remarkable curiosity. Visiting her den and tracking her movements for months on end he eventually wins the animal’s trust and they develop a never-before-seen bond between human and wild animal.', '[{"name": "Craig Foster", "character": "Self"}, {"name": "Tom Foster", "character": "Self"}]', 'Pippa Ehrlich', NULL, '2026-07-13 21:32:40.212252');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (473, 'tt0964517', 45317, 'The Fighter', 2010, '/xfsFerGhO1h6rLk8vwLgMyQ8WVJ.jpg', '{18}', 'Boxer "Irish" Micky Ward''s unlikely road to the world light welterweight title. His Rocky-like rise was shepherded by half-brother Dicky, a boxer-turned-trainer who rebounded in life after nearly being KO''d by drugs and crime.', '[{"name": "Mark Wahlberg", "character": "Micky Ward"}, {"name": "Christian Bale", "character": "Dicky Eklund"}, {"name": "Amy Adams", "character": "Charlene Fleming"}, {"name": "Melissa Leo", "character": "Alice Ward"}, {"name": "Mickey O''Keefe", "character": "Mickey O''Keefe"}]', 'David O. Russell', NULL, '2026-07-13 21:32:40.783057');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (474, 'tt1646971', 82702, 'How to Train Your Dragon 2', 2014, '/d13Uj86LdbDLrfDoHR5aDOFYyJC.jpg', '{14,28,12,16,10751}', 'Five years after uniting the dragons and Vikings of Berk, Hiccup and Toothless soar beyond their homeland, charting the vast unknown. During one of their adventures, the pair discover a secret cave that houses hundreds of wild dragons -- and a mysterious dragon rider with a startling connection to Hiccup. And as the ruthless dragon conqueror Drago Bludvist rises to seize control of both dragons and people alike, Hiccup must step into his role as a true leader and, alongside his friends and Toothless, protect Berk from a devastating war.', '[{"name": "Jay Baruchel", "character": "Hiccup (voice)"}, {"name": "Cate Blanchett", "character": "Valka (voice)"}, {"name": "Gerard Butler", "character": "Stoick (voice)"}, {"name": "Craig Ferguson", "character": "Gobber (voice)"}, {"name": "America Ferrera", "character": "Astrid (voice)"}]', 'Dean DeBlois', NULL, '2026-07-13 21:32:41.340443');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (475, 'tt3322420', 247645, 'Queen', 2013, '/vKLp0X2RQOuA31R3AdaYtDdKIPK.jpg', '{35,18}', 'Rani, a 24-year-old homely girl, decides to go on her honeymoon alone when her fiancé calls off the wedding. Traveling around Europe, she finds joy, makes friends, and gains new-found independence.', '[{"name": "Kangana Ranaut", "character": "Rani (Queen)"}, {"name": "Rajkummar Rao", "character": "Vijay"}, {"name": "Lisa Haydon", "character": "Vijayalakshmi"}, {"name": "Mish Boyko", "character": "Oleksander"}, {"name": "Jeffrey Ho", "character": "Taka"}]', 'Vikas Bahl', NULL, '2026-07-13 21:32:41.896397');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (476, 'tt0083922', 5961, 'Fanny and Alexander', 1982, '/q8jlA3Wc1Z987hNKRFA44g5OugC.jpg', '{14,18,9648}', 'As children in the loving Ekdahl family, Fanny and Alexander enjoy a happy life with their parents, who run a theater company. After their father dies unexpectedly, however, the siblings end up in a joyless home when their mother, Emilie, marries a stern bishop. The bleak situation gradually grows worse as the bishop becomes more controlling, but dedicated relatives make a valiant attempt to aid Emilie, Fanny and Alexander.', '[{"name": "Pernilla Allwin", "character": "Fanny Ekdahl"}, {"name": "Bertil Guve", "character": "Alexander Ekdahl"}, {"name": "Jan Malmsjö", "character": "Bishop Edvard Vergerus"}, {"name": "Ewa Fröling", "character": "Emilie Ekdahl"}, {"name": "Gunn Wållgren", "character": "Helena Ekdahl"}]', 'Ingmar Bergman', NULL, '2026-07-13 21:32:42.473054');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (478, 'tt1182345', 17431, 'Moon', 2009, '/35IU0Mq0zFsN1mYwDGts5mKc77n.jpg', '{878,18}', 'With only three weeks left in his three-year contract, Sam Bell is eager to return to Earth. Stationed alone at a Moon-based facility with his computer assistant GERTY, an unexpected accident sets off a series of unsettling events that shake his isolation.', '[{"name": "Sam Rockwell", "character": "Sam Bell"}, {"name": "Kevin Spacey", "character": "GERTY (voice)"}, {"name": "Dominique McElligott", "character": "Tess Bell"}, {"name": "Rosie Shaw", "character": "Little Eve"}, {"name": "Adrienne Shaw", "character": "Nanny"}]', 'Duncan Jones', NULL, '2026-07-13 21:32:43.631798');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (479, 'tt30953759', 1232493, 'No Other Land', 2024, '/s7XYieuZg9kMe07i9VI4bfGN4Pw.jpg', '{99}', 'This film made by a Palestinian-Israeli collective shows the destruction of the occupied West Bank''s Masafer Yatta by Israeli soldiers and the alliance which develops between the Palestinian activist Basel and Israeli journalist Yuval.', '[{"name": "Basel Adra", "character": "Self"}, {"name": "Yuval Abraham", "character": "Self"}, {"name": "Farisa Abu Aram", "character": "Self"}, {"name": "Nasser Adra", "character": "Self"}, {"name": "Harun Abu Aram", "character": "Self"}]', 'Rachel Szor', NULL, '2026-07-13 21:32:44.211395');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (480, 'tt6148156', 432139, 'Vikram Vedha', 2017, '/ob9YxdzRu5lfKgz0PNrlL45dorf.jpg', '{28,53,80,12}', 'A notorious gangster Vedha surrenders himself to encounter specialist Vikram whom he challenges every step of the way by narrating his life events in the form of riddles that needs to be solved in order to capture him.', '[{"name": "R. Madhavan", "character": "Vikram"}, {"name": "Vijay Sethupathi", "character": "Vedha"}, {"name": "Shraddha Srinath", "character": "Priya"}, {"name": "Kathir", "character": "Pulli"}, {"name": "Varalaxmi Sarathkumar", "character": "Chandra"}]', 'Pushkar', NULL, '2026-07-13 21:32:44.77826');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (481, 'tt0414387', 4348, 'Pride & Prejudice', 2005, '/o8UhmEbWPHmTUxP0lMuCoqNkbB3.jpg', '{18,10749}', 'A story of love and life among the landed English gentry during the Georgian era. Mr. Bennet is a gentleman living in Hertfordshire with his overbearing wife and five daughters, but if he dies their house will be inherited by a distant cousin whom they have never met, so the family''s future happiness and security is dependent on the daughters making good marriages.', '[{"name": "Keira Knightley", "character": "Elizabeth Bennet"}, {"name": "Matthew Macfadyen", "character": "Mr. Darcy"}, {"name": "Brenda Blethyn", "character": "Mrs. Bennet"}, {"name": "Rosamund Pike", "character": "Jane Bennet"}, {"name": "Carey Mulligan", "character": "Kitty Bennet"}]', 'Joe Wright', NULL, '2026-07-13 21:32:45.328568');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (482, 'tt1821480', 82825, 'Kahaani', 2012, '/e2eQVOrdQ8k7yYjjHKHP2nlwbTu.jpg', '{9648,53}', 'Pregnant and alone in the city of Kolkata, a woman begins a relentless search for her missing husband, only to find that nothing is what it seems.', '[{"name": "Vidya Balan", "character": "Vidya Bagchi"}, {"name": "Parambrata Chatterjee", "character": "ASI Satyoki \"Rana\" Sinha"}, {"name": "Nawazuddin Siddiqui", "character": "A. Khan"}, {"name": "Saswata Chatterjee", "character": "Bob Biswas"}, {"name": "Kharaj Mukherjee", "character": "Sub-Inspector Chatterjee"}]', 'Sujoy Ghosh', NULL, '2026-07-13 21:32:45.926861');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (483, 'tt0310793', 1430, 'Bowling for Columbine', 2002, '/4XsiTsZcNCRSkee1o0fdr5OqYRT.jpg', '{99,18}', 'This is not a film about gun control. It is a film about the fearful heart and soul of the United States, and the 280 million Americans lucky enough to have the right to a constitutionally protected Uzi. From a look at the Columbine High School security camera tapes to the home of Oscar-winning NRA President Charlton Heston, from a young man who makes homemade napalm with The Anarchist''s Cookbook to the murder of a six-year-old girl by another six-year-old. Bowling for Columbine is a journey through the US, through our past, hoping to discover why our pursuit of happiness is so riddled with violence.', '[{"name": "Michael Moore", "character": "Self"}, {"name": "George H. W. Bush", "character": "Self"}, {"name": "George W. Bush", "character": "Self"}, {"name": "Charlton Heston", "character": "Self - NRA President"}, {"name": "Jacobo Árbenz", "character": "Self - President of Guatemala"}]', 'Michael Moore', NULL, '2026-07-13 21:32:46.484614');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (484, 'tt0054331', 967, 'Spartacus', 1960, '/r0Fgg1GyZgzokaiw2HFQv3oPaL2.jpg', '{36,18,12}', 'The rebellious Thracian Spartacus, born and raised a slave, is sold to Gladiator trainer Batiatus. After weeks of being trained to kill for the arena, Spartacus turns on his owners and leads the other slaves in rebellion. As the rebels move from town to town, their numbers swell as escaped slaves join their ranks. Under the leadership of Spartacus, they make their way to southern Italy, where they will cross the sea and return to their homes.', '[{"name": "Kirk Douglas", "character": "Spartacus"}, {"name": "Laurence Olivier", "character": "Marcus Licinius Crassus"}, {"name": "Jean Simmons", "character": "Varinia"}, {"name": "Charles Laughton", "character": "Sempronius Gracchus"}, {"name": "Peter Ustinov", "character": "Lentulus Batiatus"}]', 'Stanley Kubrick', NULL, '2026-07-13 21:32:47.091518');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (485, 'tt5726616', 398818, 'Call Me by Your Name', 2017, '/mZ4gBdfkhP9tvLH1DO4m4HYtiyi.jpg', '{10749,18}', 'In the summer of 1983, a 17-year-old Elio spends his days in his family''s villa in Italy. One day Oliver, a graduate student, arrives to assist Elio''s father, a professor of Greco-Roman culture. Soon, Elio and Oliver discover a summer that will alter their lives forever.', '[{"name": "Timothée Chalamet", "character": "Elio"}, {"name": "Armie Hammer", "character": "Oliver"}, {"name": "Michael Stuhlbarg", "character": "Mr. Perlman"}, {"name": "Amira Casar", "character": "Annella"}, {"name": "Esther Garrel", "character": "Marzia"}]', 'Luca Guadagnino', NULL, '2026-07-13 21:32:47.650305');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (486, 'tt4034228', 334541, 'Manchester by the Sea', 2016, '/o9VXYOuaJxCEKOxbA86xqtwmqYn.jpg', '{18}', 'After his older brother passes away, Lee Chandler is forced to return home to care for his 16-year-old nephew. There he is compelled to deal with a tragic past that separated him from his family and the community where he was born and raised.', '[{"name": "Casey Affleck", "character": "Lee Chandler"}, {"name": "Lucas Hedges", "character": "Patrick Chandler"}, {"name": "Michelle Williams", "character": "Randi Chandler"}, {"name": "Kyle Chandler", "character": "Joe Chandler"}, {"name": "C.J. Wilson", "character": "George"}]', 'Kenneth Lonergan', NULL, '2026-07-13 21:32:48.22292');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (487, 'tt0094226', 117, 'The Untouchables', 1987, '/tPq0R4jTO4Ey8ZspFaWK9wGA4Ls.jpg', '{80,36,53}', 'Elliot Ness, an ambitious prohibition agent, is determined to take down Al Capone. In order to achieve this goal, he forms a group given the nickname “The Untouchables”.', '[{"name": "Kevin Costner", "character": "Eliot Ness"}, {"name": "Sean Connery", "character": "Jim Malone"}, {"name": "Robert De Niro", "character": "Al Capone"}, {"name": "Charles Martin Smith", "character": "Oscar Wallace"}, {"name": "Andy Garcia", "character": "George Stone"}]', 'Brian De Palma', NULL, '2026-07-13 21:32:48.78348');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (488, 'tt0106977', 5503, 'The Fugitive', 1993, '/b3rEtLKyOnF89mcK75GXDXdmOEf.jpg', '{28,53,18}', 'Wrongfully convicted of murdering his wife and sentenced to death, Richard Kimble escapes from the law in an attempt to find the real killer and clear his name.', '[{"name": "Harrison Ford", "character": "Richard Kimble"}, {"name": "Tommy Lee Jones", "character": "Samuel Gerard"}, {"name": "Joe Pantoliano", "character": "Cosmo Renfro"}, {"name": "Jeroen Krabbé", "character": "Charles Nichols"}, {"name": "Daniel Roebuck", "character": "Biggs"}]', 'Andrew Davis', NULL, '2026-07-13 21:32:49.356067');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (489, 'tt0044079', 845, 'Strangers on a Train', 1951, '/ihC083U7ef56Ui4x0P0dobojrZ1.jpg', '{80,53,18}', 'A charming psychopath tries to coerce a tennis star into his theory that two strangers can commit the perfect crime by exchanging murders—each killing the other’s most-hated person.', '[{"name": "Farley Granger", "character": "Guy Haines"}, {"name": "Ruth Roman", "character": "Anne Morton"}, {"name": "Robert Walker", "character": "Bruno Antony"}, {"name": "Leo G. Carroll", "character": "Sen. Morton"}, {"name": "Patricia Hitchcock", "character": "Barbara Morton"}]', 'Alfred Hitchcock', NULL, '2026-07-13 21:32:49.936876');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (490, 'tt1016150', 49046, 'All Quiet on the Western Front', 2022, '/2IRjbi9cADuDMKmHdLK7LaqQDKA.jpg', '{10752,18}', 'Paul Baumer and his friends Albert and Muller, egged on by romantic dreams of heroism, voluntarily enlist in the German army. Full of excitement and patriotic fervour, the boys enthusiastically march into a war they believe in. But once on the Western Front, they discover the soul-destroying horror of World War I.', '[{"name": "Felix Kammerer", "character": "Paul Bäumer"}, {"name": "Albrecht Schuch", "character": "Stanislaus ''Kat'' Katczinsky"}, {"name": "Aaron Hilmer", "character": "Albert Kropp"}, {"name": "Moritz Klaus", "character": "Franz Müller"}, {"name": "Adrian Grünewald", "character": "Ludwig Behm"}]', 'Edward Berger', NULL, '2026-07-13 21:32:50.501476');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (491, 'tt0019254', 780, 'The Passion of Joan of Arc', 1928, '/tAgV9yxY6AC1bsPt3qJJQpD4s8.jpg', '{18,36}', 'A classic of the silent age, this film tells the story of the doomed but ultimately canonized 15th-century teenage warrior. On trial for claiming she''d spoken to God, Jeanne d''Arc is subjected to inhumane treatment and scare tactics at the hands of church court officials. Initially bullied into changing her story, Jeanne eventually opts for what she sees as the truth. Her punishment, a famously brutal execution, earns her perpetual martyrdom.', '[{"name": "Maria Falconetti", "character": "Jeanne d''Arc"}, {"name": "Eugène Silvain", "character": "Bishop Pierre Cauchon"}, {"name": "André Berley", "character": "Jean d''Estivet"}, {"name": "Maurice Schutz", "character": "Nicolas Loyseleur"}, {"name": "Antonin Artaud", "character": "Jean Massieu"}]', 'Carl Theodor Dreyer', NULL, '2026-07-13 21:32:51.107428');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (492, 'tt0783233', 4347, 'Atonement', 2007, '/hMRIyBjPzxaSXWM06se3OcNjIQa.jpg', '{18,10749}', 'A young girl irrevocably changes the course of several lives when she accuses her older sister''s lover of a crime he did not commit.', '[{"name": "James McAvoy", "character": "Robbie Turner"}, {"name": "Keira Knightley", "character": "Cecilia Tallis"}, {"name": "Saoirse Ronan", "character": "Briony Tallis (Age 13)"}, {"name": "Romola Garai", "character": "Briony Tallis (Age 18)"}, {"name": "Vanessa Redgrave", "character": "Briony Tallis (Age 77)"}]', 'Joe Wright', NULL, '2026-07-13 21:32:51.67598');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (493, 'tt1555149', 47931, 'Elite Squad: The Enemy Within', 2010, '/c7yCrf3PTSdp6RMGktZQhzFcFFM.jpg', '{18,28,80}', 'After a bloody invasion of the BOPE in the High-Security Penitentiary Bangu 1 in Rio de Janeiro to control a rebellion of interns, the Lieutenant-Colonel Roberto Nascimento and the second in command Captain André Matias are accused by the Human Right Aids member Diogo Fraga of execution of prisoners. Matias is transferred to the corrupted Military Police and Nascimento is exonerated from the BOPE by the Governor.', '[{"name": "Wagner Moura", "character": "Tenente-Coronel Nascimento"}, {"name": "Irandhir Santos", "character": "Diogo Fraga"}, {"name": "André Ramiro", "character": "André Matias"}, {"name": "Milhem Cortaz", "character": "Tenente-Coronel Fábio"}, {"name": "Maria Ribeiro", "character": "Rosane"}]', 'José Padilha', NULL, '2026-07-13 21:32:52.252215');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (494, 'tt0104257', 881, 'A Few Good Men', 1992, '/rLOk4z9zL1tTukIYV56P94aZXKk.jpg', '{18}', 'When cocky military lawyer Lt. Daniel Kaffee and his co-counsel, Lt. Cmdr. JoAnne Galloway, are assigned to a murder case, they uncover a hazing ritual that could implicate high-ranking officials such as shady Col. Nathan Jessep.', '[{"name": "Tom Cruise", "character": "Lt. Daniel Kaffee"}, {"name": "Jack Nicholson", "character": "Col. Nathan R. Jessep"}, {"name": "Demi Moore", "character": "Lt. Cdr. JoAnne Galloway"}, {"name": "Kevin Bacon", "character": "Capt. Jack Ross"}, {"name": "Kiefer Sutherland", "character": "Lt. Jonathan Kendrick"}]', 'Rob Reiner', NULL, '2026-07-13 21:32:52.806388');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (495, 'tt0379786', 16320, 'Serenity', 2005, '/4sqUOaPFoP2W81mq1UYqZqf5WzA.jpg', '{878,28,12,53}', 'A group of rebels travel the outskirts of space evading the sinister Alliance regime. Their lives of smuggling and cargo-running are interrupted by a psychic passenger who harbours a dangerous secret. Soon, the crew find themselves being pursued by an Alliance agent who will stop at nothing to find them.', '[{"name": "Nathan Fillion", "character": "Malcolm ''Mal'' Reynolds"}, {"name": "Summer Glau", "character": "River Tam"}, {"name": "Gina Torres", "character": "Zoë Alleyne Washburne"}, {"name": "Alan Tudyk", "character": "Hoban ''Wash'' Washburne"}, {"name": "Morena Baccarin", "character": "Inara Serra"}]', 'Joss Whedon', NULL, '2026-07-13 21:32:53.36532');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (496, 'tt0374546', 113, 'Spring, Summer, Fall, Winter... and Spring', 2003, '/6SQQ5REuAz7k0FMQ9mSCT40T2LN.jpg', '{18}', 'An isolated lake, where an old monk lives in a small floating temple. The monk has a young boy living with him, learning to become a monk. We watch as seasons and years pass by.', '[{"name": "Oh Young-soo", "character": "Old Monk"}, {"name": "Kim Ki-duk", "character": "Adult Monk"}, {"name": "Kim Young-min", "character": "Young Adult Monk"}, {"name": "Seo Jae-kyeong", "character": "Boy Monk"}, {"name": "Kim Jong-ho", "character": "Child Monk"}]', 'Kim Ki-duk', NULL, '2026-07-13 21:32:53.92187');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (497, 'tt11555492', 856437, 'Farha', 2021, '/X4kRsdyP9FgMfKKn9LZiVscZY5.jpg', '{18,36,10752}', 'Palestine, 1948. After the withdrawal of the British occupiers, tensions rise between Arabs and Jews. Meanwhile, Farha, the smart daughter of the mayor of a small village, unaware of the coming tragedy, dreams of going to study in the big city.', '[{"name": "Ashraf Barhom", "character": "Abu Farha"}, {"name": "Karam Taher", "character": "Farha"}, {"name": "Tala Gammoh", "character": "Farida"}, {"name": "Ali Suliman", "character": "Abu Walid"}, {"name": "Sameera Asir", "character": "Myassar (Um Mohammad)"}]', 'Darin J. Sallam', NULL, '2026-07-13 21:32:54.511891');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (498, 'tt2265171', 180299, 'The Raid 2', 2014, '/mlGuKlIDLdPhYjz1QBXi0FmyYik.jpg', '{28,80,53}', 'After fighting his way through an apartment building populated by an army of dangerous criminals and escaping with his life, SWAT team member Rama goes undercover, joining a powerful Indonesian crime syndicate to protect his family and uncover corrupt members of his own force.', '[{"name": "Iko Uwais", "character": "Rama"}, {"name": "Arifin Putra", "character": "Ucok"}, {"name": "Tio Pakusadewo", "character": "Bangun"}, {"name": "Oka Antara", "character": "Eka"}, {"name": "Alex Abbad", "character": "Bejo"}]', 'Gareth Evans', NULL, '2026-07-13 21:32:55.072869');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (499, 'tt9477520', 576928, 'Asuran', 2019, '/Elnp3XrAlMM30dil8rbL7D9XeP.jpg', '{28,18}', 'A family from the underprivileged class is on the run after the teenaged son kills a rich man from the upper caste. Can the pacifist father be able to save his hot-blooded son?', '[{"name": "Dhanush", "character": "Sivasaamy"}, {"name": "Manju Warrier", "character": "Pachaiyammal"}, {"name": "Ken Karunaas", "character": "Chidambaram"}, {"name": "Teejay", "character": "Vel Murugan"}, {"name": "Pasupathy", "character": "Murugesan"}]', 'Vetrimaaran', NULL, '2026-07-13 21:32:55.635463');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (500, 'tt0084503', 12104, 'Pink Floyd: The Wall', 1982, '/aElHyIdF5jmctFGhlhhaPFsbBJC.jpg', '{10402,18}', 'A troubled rock star descends into madness in the midst of his physical and social isolation from everyone.', '[{"name": "Bob Geldof", "character": "Pink"}, {"name": "Christine Hargreaves", "character": "Pink''s Mother"}, {"name": "James Laurenson", "character": "Pink''s Father"}, {"name": "Eleanor David", "character": "Pink''s Wife"}, {"name": "Kevin McKeon", "character": "Young Pink"}]', 'Alan Parker', NULL, '2026-07-13 21:32:56.238849');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (216, 'tt0381681', 80, 'Before Sunset', 2004, '/4sW5XH9ZfYXpvFzev00S1IGAEbg.jpg', '{18,10749}', 'Nine years later, Jesse travels across Europe giving readings from a book he wrote about the night he spent in Vienna with Celine. After his reading in Paris, Celine finds him, and they spend part of the day together before Jesse has to again leave for a flight. They are both in relationships now, and Jesse has a son, but as their strong feelings for each other start to return, both confess a longing for more.', '[{"name": "Ethan Hawke", "character": "Jesse"}, {"name": "Julie Delpy", "character": "Céline"}, {"name": "Vernon Dobtcheff", "character": "Bookstore Manager"}, {"name": "Louise Lemoine Torrès", "character": "Journalist #1"}, {"name": "Rodolphe Pauly", "character": "Journalist #2"}]', 'Richard Linklater', '2026-07-13 21:34:09.977+00', '2026-07-13 21:30:11.424398');
